INSERT INTO `mount` (`Name`, `SourceText`, `Description`, `ID`, `MountTypeID`, `Flags`, `SourceTypeEnum`, `SourceSpellID`, `PlayerConditionID`, `MountFlyRideHeight`, `UiModelSceneID`, `MountSpecialRiderAnimKitID`, `MountSpecialSpellVisualKitID`, `VerifiedBuild`) VALUES
('Carcinized Zerethsteed', '|cFFFFD200Quest:|r Leading Motives', 'The few of these mysterious creatures that remain appear to be impossibly old, almost timeless. Perhaps they were created by the First Ones, because no schematic to synthesize these has yet been discovered.', 1552, 248, 0, 1, 359545, 0, 0, 4, 0, 0, 42423),
('Cosmic Gladiator\'s Soul Eater', '|cFFFFD200Achievement: |rGladiator: Shadowlands Season 3|n|cFFFFD200Category: |rPlayer vs. Player', 'This soul eater\'s gaze unnerves you. Best not meet its eyes for too long.', 1572, 248, 192, 5, 365559, 0, 0, 4, 0, 0, 42423),
('Unchained Gladiator\'s Soul Eater', '|cFFFFD200Achievement: |rGladiator: Shadowlands Season 2|n|cFFFFD200Category: |rPlayer vs. Player', 'This soul eater\'s gaze unnerves you. Best not meet its eyes for too long.', 1480, 248, 192, 5, 353036, 0, 0, 4, 0, 0, 42423),
('Shimmering Aurelid', '|cFFFFD200Achievement: |rGlory of the Sepulcher Raider|n|cFFFFD200Category: |rDungeons & Raids', 'Though it was once created to defend the Sepulcher of the First Ones, with its primary function now completed, it now obediently follows your command.', 1549, 407, 2192, 5, 359379, 0, 0, 44, 0, 0, 42423);
