INSERT INTO `scene_script_global_text` (`ID`, `Name`, `Script`, `VerifiedBuild`) VALUES
(35063, '[4] 9.1 Broker Games - Matching - Functions (Tutorial)', 'and GameBoard[i] and GameBoard[i][j] then\n\t\t\t\tGameBoard[i][j]:SetInteractible(false)\n\t\t\t\tGameBoard[i][j].interactible=nil\n\t\t\tend\n\t\tend\n\tend\n\tfor _,LoopNode in pairs(PassedList) do\n\t\tif LoopNode then\n\t\t\tLoopNode:SetInteractible(true)\n\t\t\tLoopNode.interactible=true\n\t\tend\n\tend\nend\n\nfunction DisplayBoard()\n\tif not GameBoard then\n\t\tBroadcast(\"[CS35056] No GameBoard to display!\")\n\t\treturn\n\tend\n\tfor i=1,MaxDimensions[\"MaxRows\"] do\n\t\tfor j=1,MaxDimensions[\"MaxCols\"] do\n\t\t\tif GameBoard and GameBoard[i] and GameBoard[i][j] then\n\t\t\t\tif GameBoard[i][j].SpellVisuals and #GameBoard[i][j].SpellVisuals>0 then\n\t\t\t\t\tGameBoard[i][j]:SetInteractible(true)\n\t\t\t\t\tGameBoard[i][j].interactible=true\n\t\t\t\telse\n\t\t\t\t\tGameBoard[i][j]:SetInteractible(false)\n\t\t\t\t\tGameBoard[i][j].interactible=nil\n\t\t\t\tend\n\t\t\telse\n\t\t\tend\n\t\tend\n\tend\nend\n\nfunction GameIsFinished()\n\tif GameBoard and GameBoard.CurrentScore and GameBoard.CurrentScore>2 then\n\t\tscene:TriggerServerEvent(\"Success\")\n\t\treturn true\t\t\t\n\telse\n\t\treturn false\n\tend\nend', 42423),
(35059, '[3] 9.1 Broker Games - Matching - Functions (Tutorial)', 'scene:GetTransform().yaw, 0, 0)\n\tNodeCreateData.scale=NODE_SCALE\n\tNodeCreateData.interactible=true\n\t\n\tlocal thisNode = scene:SpawnActor(NodeCreateData)\n\tthisNode:SetInteractCursor(\"interact\", CursorRange.RangeFromPlayer, 20, nil)\n\tthisNode.selected = false\n\tthisNode.offset = nodeOffset\n\n\tthisNode.Row=Row\n\tthisNode.Col=Column\n\tthisNode.IsANode=true\n\t\n\tthisNode.SpellVisuals={}\n\t\n\tRideVehicleActor(thisNode, Player, 0, AttachmentPoint.Base,BOARD_OFFSET+nodeOffset+VEHICLE_OFFSET_Z,Vector:New(0,0,0))--scene:GetTransform().yaw\n\tAddInteractCoroutine(thisNode)\n\n\treturn thisNode\n\nend\n\nfunction CreateGameBoard(PassedLocation)\n\tDisableInteraction()\n\tlocal BoardCreateData = ActorCreateData:Default()\n\tBoardCreateData.groundSnap = true\n\tBoardCreateData.interactible = false\n\tBoardCreateData.selectable = false\n\tBoardCreateData.floatingTooltip = false\n\tBoardCreateData.scale = BOARD_SCALE\n\tBoardCreateData.creatureDisplayID = BOARD_CDI\n\tBoardCreateData.offset=Vector:New(0,0,0)\n\t\n\tlocal MyBoard = scene:SpawnActor(BoardCreateData)\n\tMyBoard.selected = false\n\ttable.insert(SpellVisualsToClear,{MyBoard,MyBoard:PlaySpellStateVisual(BOARD_STATE_VISUAL)})\n\t\t\n\tRideVehicleActor(MyBoard, Player, 0, AttachmentPoint.Base,Vector:New(0.15,1.35,0.05)+BOARD_OFFSET+VEHICLE_OFFSET_Z,Vector:New(0,0,0))--scene:GetTransform().yaw\n\tConstructDeck()\n\t\n\tMakeGameNodes()\n\t\t\n\tScrambleBoard()\n\t\n\tDisplayBoard()\n\t\n\tEnableInteraction()\n\t\n\tDisplayOpening()\n\t\t\n\t--RideVehicleActor(MyBoard, Player, 0, AttachmentPoint.Base,Vector:New(0,0,0),Vector:New(scene:GetTransform().yaw,0,0))\nend\n\nfunction MakeGameNodes()\t\n\tfor LoopRow=1,MaxDimensions[\"MaxRows\"] do\n\t\tGameBoard[LoopRow]={}\n\t\tfor LoopCol=1, MaxDimensions[\"MaxCols\"] do\n\t\t\tGameBoard[LoopRow][LoopCol]=CreateNode(LoopRow,LoopCol)\n\t\tend\n\tend\nend\n\nfunction IsNode(PassedRow,PassedCol)\n\tif GameBoard then\n\t\tif GameBoard[PassedRow] then\n\t\t\tif GameBoard[PassedRow][PassedCol] then\n\t\t\t\treturn GameBoard[PassedRow][PassedCol].IsANode\n\t\t\tend\n\t\tend\n\tend\nend\n\nfunction ClearBoard()\n\tif not GameBoard then return end\n\tfor i=1,MaxDimensions[\"MaxRows\"] do\n\t\tfor j=1,MaxDimensions[\"MaxCols\"] do\n\t\t\tif GameBoard and GameBoard[i] and GameBoard[i][j] then\n\t\t\t\tif GameBoard[i][j].SpellVisual then\n\t\t\t\t\tGameBoard[i][j]:ClearSpellVisual(GameBoard[i][j].SpellVisual)\n\t\t\t\tend\n\t\t\t\tif GameBoard[i][j].Peg then\n\t\t\t\t\tGameBoard[i][j].Peg:Despawn()\n\t\t\t\tend\n\t\t\t\tGameBoard[i][j]:Despawn()\n\t\t\t\tGameBoard[i][j]=nil\t\t\t\n\t\t\tend\n\t\tend\n\t\tGameBoard[i]=nil\n\tend\n\tGameBoard.CurrentCards={}\n\tGameBoard.NumCardsActive=0\n\tGameBoard.CurrentScore=0\nend\n\nfunction DisableInteraction()\n\tGameBoard.InteractionDisabled=true\nend\n\nfunction EnableInteraction()\n\tGameBoard.InteractionDisabled=nil\nend\n\nfunction InteractionAllowed()\n\tif not GameBoard then return false end\n\treturn not GameBoard.InteractionDisabled\nend\n\nfunction FailGame()\n\tscene:TriggerServerEvent(\"Failure\")\n\tDisableInteraction()\n\tClearBoard()\n\tWait(3)\n\tRestartGame()\nend\n\nfunction RestartGame()\n\t--Broadcast(\"Restarting Game\")\n\tDisableInteraction()\n\tClearBoard()\n\tConstructDeck()\n\tMakeGameNodes()\n\t--GameParameters[\"movesremaining\"]=GameParameters[\"maxmoves\"]\n\tScrambleBoard()\n\tDisplayBoard(GameParameters)\n\tEnableInteraction()\n\tDisplayOpening()\nend\n\n\nfunction DisplayOpening()\n\tscene:PlaySoundKit(193446,true,scene:GetPosition())\t\n\tif GameBoard and not GameBoard.AlreadyIntroducedOnce then\n\t\tGameBoard.AlreadyIntroducedOnce=true\n\t\tscene:TriggerServerEvent(\"IntroA\")\n\t\tWait(5)\n\t\tscene:TriggerServerEvent(\"IntroB\")\n\t\tWait(13)\n\tend\n\tscene:TriggerServerEvent(\"IntroC\")\n\tWait(5)\nend\n\n\nfunction MakeAllButListUninteractible(PassedList)\n\tif not GameBoard then\n\t\tBroadcast(\"[CS35056] No GameBoard to display!\")\n\t\treturn\n\tend\n\tfor i=1,MaxDimensions[\"MaxRows\"] do\n\t\tfor j=1,MaxDimensions[\"MaxCols\"] do\n\t\t\tif GameBoard ', 42423),
(35058, '[2] 9.1 Broker Games - Matching - Functions (Tutorial)', '\tend\n\tfor i=1,GAMEBOARD_ROWS do\n\t\tfor j=1,GAMEBOARD_COLUMNS do\n\t\t\tif GameBoard[i][j] then\n\t\t\t\tDespawnNode(i,j)\n\t\t\tend\n\t\tend\n\tend\nend\n\nfunction CompleteSet()\n\t--Broadcast(\"Completed a set!\")\n\tlocal Row,Col\n\tlocal NewIndices={}\n\tscene:TriggerServerEvent(\"CompleteOne\")\n\tfor LoopIndex,LoopCard in pairs(GameBoard.CurrentCards) do\n\t\tRow,Col=0,0\n\t\tCol=LoopIndex%100\n\t\tRow=(LoopIndex-Col)/100\n\t\t--Broadcast(\"LoopIndex[\"..LoopIndex..\"] turns into: Row[\"..Row..\"], Col[\"..Col..\"]\")\n\t\tDespawnNode(Row,Col)\n\t\ttable.insert(NewIndices,{Row,Col})\n\tend\t\n\tGameBoard.CurrentCards={}\n\tGameBoard.NumCardsActive=0\n\tGameBoard.CurrentScore=GameBoard.CurrentScore+1\n\tWait(2)\n\t--for _,LoopPairing in pairs(NewIndices) do\n\t--\tMakeNewCard(LoopPairing[1],LoopPairing[2])\n\t--end\n\t--Broadcast(\"--------------------\")\nend\n\nfunction MakeNewCard(PassedRow,PassedCol)\n\tGameBoard[PassedRow][PassedCol]=CreateNode(PassedRow,PassedCol)\n\tAddNodeVisual(GameBoard[PassedRow][PassedCol],table.remove(GameBoard.Deck))\nend\n\nfunction CheckCurrentCards()\n\tDisableInteraction()\n\tif GameBoard.NumCardsActive>2 then\n\t\t--Broadcast(\"Checking 3 cards!\")\n\t\tlocal ShouldScore=false\n\t\tlocal ValidBorders,ValidBorderCounts,ValidShapes,ValidShapeCounts=false,false,false,false\n\t\tlocal Cards={}\n\t\tfor Position,LoopCard in pairs(GameBoard.CurrentCards) do\n\t\t\t--Broadcast(\"Checking Position: \"..Position)\n\t\t\ttable.insert(Cards,LoopCard)\n\t\tend\n\t\tlocal AllSame,AllDifferent=false,false\n\t\tfor _,LoopAttribute in pairs({\"Border\",\"Shape\",\"BorderCount\",\"ShapeCount\"}) do\n\t\t\tif Cards[1][LoopAttribute]==Cards[2][LoopAttribute] and Cards[1][LoopAttribute]==Cards[3][LoopAttribute] then\n\t\t\t\tAllSame=true\n\t\t\telseif Cards[1][LoopAttribute]~=Cards[2][LoopAttribute] and Cards[1][LoopAttribute]~=Cards[3][LoopAttribute]\n\t\t\t\tand Cards[2][LoopAttribute]~=Cards[3][LoopAttribute] then\n\t\t\t\t\tAllDifferent=true\n\t\t\tend\n\t\t\tif not (AllSame or AllDifferent) then\n\t\t\t\tFailCurrentCards(LoopAttribute)\n\t\t\t\treturn\n\t\t\tend\n\t\t\tAllSame,AllDifferent=false,false\n\t\tend\n\t\tCompleteSet()\n\telse\n\t\t--Broadcast(\"#CurrentCards: \"..GameBoard.NumCardsActive)\n\tend\n\tEnableInteraction()\nend\n\n\nfunction DespawnNode(PassedRow,PassedCol)\n\t--PassedIndex is still in the has form (Row*100+Col)\n\tlocal MappedNode=GameBoard[PassedRow][PassedCol]\n\twhile #MappedNode.SpellVisuals>0 do\n\t\tMappedNode:ClearSpellVisual(table.remove(MappedNode.SpellVisuals))\n\tend\n\tMappedNode:Despawn()\n\tGameBoard[PassedRow][PassedCol]=nil\nend\n\nfunction AddNodeVisual(PassedNode,PassedVisual)\n\tif PassedNode.SpellVisuals then\n\t\twhile #PassedNode.SpellVisuals>0 do\n\t\t\tPassedNode:ClearSpellVisual(table.remove(PassedNode.SpellVisuals))\n\t\tend\n\tend\n\tif PassedVisual then\n\t\tif PassedVisual[\"Border\"] and PassedVisual[\"BorderCount\"] then\n\t\t\tPassedNode[\"Border\"]=PassedVisual[\"Border\"]\n\t\t\tPassedNode[\"BorderCount\"]=PassedVisual[\"BorderCount\"]\n\t\t\ttable.insert(PassedNode.SpellVisuals,PassedNode:PlaySpellStateVisual(BORDER_VISUAL_LOOKUP_TABLE[PassedVisual[\"Border\"]][PassedVisual[\"BorderCount\"]]))\n\t\tend\n\t\tif PassedVisual[\"Shape\"] and PassedVisual[\"ShapeCount\"] then\n\t\t\tPassedNode[\"Shape\"]=PassedVisual[\"Shape\"]\n\t\t\tPassedNode[\"ShapeCount\"]=PassedVisual[\"ShapeCount\"]\n\t\t\ttable.insert(PassedNode.SpellVisuals,\n\t\t\t\t\tPassedNode:PlaySpellStateVisual(\n\t\t\t\t\t\tSHAPE_VISUAL_LOOKUP_TABLE[PassedVisual[\"Shape\"]][PassedVisual[\"ShapeCount\"]]\n\t\t\t\t\t)\n\t\t\t\t)\n\t\tend\n\telse\t\n\t\tPassedNode.SpellVisual=nil\n\tend\nend\n\nfunction ScrambleBoard()\n\tfor i=1,MaxDimensions[\"MaxRows\"] do\n\t\tfor j=1,MaxDimensions[\"MaxCols\"] do\n\t\t\tAddNodeVisual(GameBoard[i][j],table.remove(GameBoard.Deck))\n\t\tend\n\tend\nend\n\nfunction CreateNode(Row,Column,PassedValue)\n\n\tNodeCreateData.creatureDisplayID = NODE_CDI\n\tlocal nodeOffset = Vector:New(0,Column*COLUMN_WIDTH,Row*ROW_HEIGHTH)\n\tNodeCreateData.transform = Transform:New(BOARD_OFFSET+nodeOffset, ', 42423),
(35057, '[1] 9.1 Broker Games - Matching - Functions (Tutorial)', 'do\n\t\t\t\t\tfor LoopBorderCount=1,3 do\n\t\t\t\t\t\tLoopIndex=(LoopBorder*1000)+(LoopShape*100)+(LoopShapeCount*10)+LoopBorderCount\n\t\t\t\t\t\tBaseDeck[LoopIndex]={\n\t\t\t\t\t\t\t\t\t\t\t[\"Border\"]=Borders[LoopBorder],\n\t\t\t\t\t\t\t\t\t\t\t[\"Shape\"]=Shapes[LoopShape],\n\t\t\t\t\t\t\t\t\t\t\t[\"ShapeCount\"]=LoopShapeCount,\n\t\t\t\t\t\t\t\t\t\t\t[\"BorderCount\"]=LoopBorderCount\n\t\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\ttable.insert(Indices,LoopIndex)\n\t\t\t\t\t\t--Broadcast(\"Inserted: \"..string.format(FormatString,Borders[LoopBorder],Shapes[LoopShape],LoopBorderCount,LoopShapeCount))\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\t\n\t\tend\n\t\tShuffleTable(Indices)\n\t\tlocal LoopCard_A,LoopCard_B,LoopCard_C\n\t\tlocal TryIndex\n\t\tfor i=1,3 do --making 3 groups of cards\n\t\t\tLoopCard_C={}\n\t\t\t--Pull two cards from the Deck, compare each of their elements:\n\t\t\t--  If same, pick a card that also has the same value, else different\n\t\t\trepeat\n\t\t\t\tTryIndex=table.remove(Indices)\n\t\t\t\tLoopCard_A=BaseDeck[TryIndex]\n\t\t\tuntil LoopCard_A or #Indices<1\n\t\t\tBaseDeck[TryIndex]=nil\n\t\t\trepeat\n\t\t\t\tTryIndex=table.remove(Indices)\n\t\t\t\tLoopCard_B=BaseDeck[TryIndex]\n\t\t\tuntil LoopCard_B or #Indices<1\n\t\t\tBaseDeck[TryIndex]=nil\n\t\t\tif LoopCard_A[\"Border\"]==LoopCard_B[\"Border\"] then\n\t\t\t\tLoopCard_C[\"Border\"]=LoopCard_A[\"Border\"]\n\t\t\telse\n\t\t\t\tfor i=1,3 do\n\t\t\t\t\tif i==BorderRemap[LoopCard_A[\"Border\"]] or i==BorderRemap[LoopCard_B[\"Border\"]] then\n\t\t\t\t\telse\n\t\t\t\t\t\tLoopCard_C[\"Border\"]=Borders[i]\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\t\t\n\t\t\tif LoopCard_A[\"Shape\"]==LoopCard_B[\"Shape\"] then\n\t\t\t\tLoopCard_C[\"Shape\"]=LoopCard_A[\"Shape\"]\n\t\t\telse\n\t\t\t\tfor i=1,3 do\n\t\t\t\t\tif i==ShapeRemap[LoopCard_A[\"Shape\"]] or i==ShapeRemap[LoopCard_B[\"Shape\"]] then\n\t\t\t\t\telse\n\t\t\t\t\t\tLoopCard_C[\"Shape\"]=Shapes[i]\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\t\t\n\t\t\tif LoopCard_A[\"ShapeCount\"]==LoopCard_B[\"ShapeCount\"] then\n\t\t\t\tLoopCard_C[\"ShapeCount\"]=LoopCard_A[\"ShapeCount\"]\n\t\t\telse\n\t\t\t\tfor i=1,3 do\n\t\t\t\t\tif i==LoopCard_A[\"ShapeCount\"] or i==LoopCard_B[\"ShapeCount\"] then\n\t\t\t\t\telse\n\t\t\t\t\t\tLoopCard_C[\"ShapeCount\"]=i\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\t\t\n\t\t\tif LoopCard_A[\"BorderCount\"]==LoopCard_B[\"BorderCount\"] then\n\t\t\t\tLoopCard_C[\"BorderCount\"]=LoopCard_A[\"BorderCount\"]\n\t\t\telse\n\t\t\t\tfor i=1,3 do\n\t\t\t\t\tif i==LoopCard_A[\"BorderCount\"] or i==LoopCard_B[\"BorderCount\"] then\n\t\t\t\t\telse\n\t\t\t\t\t\tLoopCard_C[\"BorderCount\"]=i\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\n\t\t\tLoopIndex=(BorderRemap[LoopCard_C[\"Border\"]]*1000)+(ShapeRemap[LoopCard_C[\"Shape\"]]*100)+(LoopCard_C[\"ShapeCount\"]*10)+LoopCard_C[\"BorderCount\"]\n\t\t\tBaseDeck[LoopIndex]=nil\n\t\t\t\n\t\t\t--Broadcast(\"Inserting [A]: \"..string.format(FormatString,LoopCard_A[\"Border\"],LoopCard_A[\"Shape\"],LoopCard_A[\"ShapeCount\"],LoopCard_A[\"BorderCount\"]))\n\t\t\t--Broadcast(\"Inserting [B]: \"..string.format(FormatString,LoopCard_B[\"Border\"],LoopCard_B[\"Shape\"],LoopCard_B[\"ShapeCount\"],LoopCard_B[\"BorderCount\"]))\n\t\t\t--Broadcast(\"Inserting [C]: \"..string.format(FormatString,LoopCard_C[\"Border\"],LoopCard_C[\"Shape\"],LoopCard_C[\"ShapeCount\"],LoopCard_C[\"BorderCount\"]))\n\t\t\t--[[table.insert(GameBoard.Deck,LoopCard_A)\n\t\t\ttable.insert(GameBoard.Deck,LoopCard_B)\n\t\t\ttable.insert(GameBoard.Deck,LoopCard_C)--]]\n\t\t\ttable.insert(GameBoard.RestoreDeck,LoopCard_A)\n\t\t\ttable.insert(GameBoard.RestoreDeck,LoopCard_B)\n\t\t\ttable.insert(GameBoard.RestoreDeck,LoopCard_C)\n\t\tend\n\t\t\n\t\t--At this point we should 3 groups of Cards\n\t\tShuffleTable(GameBoard.RestoreDeck) \n\tend\n\tGameBoard.Deck={}\n\tfor _,LoopCard in pairs(GameBoard.RestoreDeck) do\n\t\t--Broadcast(\"Restoring LoopCard: \"..string.format(FormatString,LoopCard[\"Border\"],LoopCard[\"Shape\"],LoopCard[\"ShapeCount\"],LoopCard[\"BorderCount\"]))\n\t\ttable.insert(GameBoard.Deck,LoopCard)\n\tend\n\t--Broadcast(\"#ChosenCards: \"..#GameBoard.Deck)\nend\n\n\nfunction CleanUpGame()\n\tlocal LoopEntry\n\twhile #SpellVisualsToClear>0 do\n\t\tLoopEntry=table.remove(SpellVisualsToClear)\n\t\tif LoopEntry[1] and LoopEntry[2] then\n\t\t\tLoopEntry[1]:ClearSpellVisual(LoopEntry[2])\n\t\tend\n', 42423),
(35056, '9.1 Broker Games - Matching - Functions (Tutorial)', 'local NodeCoroutine\nfunction AddInteractCoroutine(...)\n\tscene:AddCoroutineWithParams(NodeCoroutine, ...)\nend\nNodeCoroutine = function(actor)\n\twhile (true) do\n\t\tactor:WaitRightClick()\n\t\t--Broadcast(\"Clicked\")\n\t\tif InteractionAllowed() and actor.IsANode then\n\t\t\tDisableInteraction()\n\t\t\tAddClickedNode(actor)\n\t\t\tWait(.3)\n\t\t\tEnableInteraction()\n\t\telse\n\t\tend\n\tend\nend\n\nfunction AddClickedNode(PassedNode)\n\tlocal FormatString=\"Border[%s] Shape[%s] BorderCount[%s] ShapeCount[%s]\"\n\tBroadcast(\"Clicked on: \"..string.format(FormatString,PassedNode[\"Border\"],PassedNode[\"Shape\"],PassedNode[\"BorderCount\"],PassedNode[\"ShapeCount\"]))\n\tif PassedNode.CurrentlyClicked then\n\t\t--Broadcast(\"Node Already Clicked, Clearing: \"..(PassedNode.Row*100+PassedNode.Col))\n\t\tscene:PlaySoundKit(193452,true,scene:GetPosition())\t\n\t\tAddActiveCard(PassedNode.Row*100+PassedNode.Col,nil)\n\t\tPassedNode:ClearSpellVisual(PassedNode.CurrentlyClicked)\n\t\tPassedNode.CurrentlyClicked=nil\n\telse\n\t\tscene:PlaySoundKit(193452,true,scene:GetPosition())\t\n\t\tPassedNode.CurrentlyClicked=PassedNode:PlaySpellStateVisual(NODE_STATE_VISUAL_SELECTED)\n\t\t--table.insert(GameBoard.CurrentCards,PassedNode)\n\t\tAddActiveCard(PassedNode.Row*100+PassedNode.Col,PassedNode)\n\t\t--GameBoard.CurrentCards[PassedNode.Row*100+PassedNode.Col]=PassedNode\n\t\t--Broadcast(\"GameBoard[\"..PassedNode.Row*100+PassedNode.Col..\"]\")\n\t\tif not GameBoard.CurrentCards[PassedNode.Row*100+PassedNode.Col] then\n\t\t\t--Broadcast(\"Failed to allocate GameBoard[\"..PassedNode.Row*100+PassedNode.Col..\"]\")\n\t\tend\n\t\tCheckCurrentCards()\n\tend\t\t\nend\n\nfunction AddActiveCard(PassedIndex,PassedNode)\n\tGameBoard.CurrentCards[PassedIndex]=PassedNode\n\tif PassedNode then\n\t\tif not GameBoard.NumCardsActive then GameBoard.NumCardsActive=0 end\n\t\tGameBoard.NumCardsActive=GameBoard.NumCardsActive+1\n\telse\n\t\tif not GameBoard.NumCardsActive then\n\t\telse\n\t\t\tGameBoard.NumCardsActive=GameBoard.NumCardsActive-1\n\t\tend\n\tend\nend\n\nfunction FailCurrentCards(PassedReason)\n\t--Broadcast(\"Current set not valid!\")\n\tif PassedReason then\n\t\t--\"Border\",\"Shape\",\"BorderCount\",\"ShapeCount\"\n\t\t--Broadcast(\"Reason: \"..PassedReason)\n\t\tif PassedReason==\"Border\" then scene:TriggerServerEvent(\"FailBorderShapes\")\n\t\telseif PassedReason==\"BorderCount\" then scene:TriggerServerEvent(\"FailNumBorderShapes\")\n\t\telseif PassedReason==\"Shape\" then scene:TriggerServerEvent(\"FailCoreShapes\")\n\t\telseif PassedReason==\"ShapeCount\" then scene:TriggerServerEvent(\"FailNumCoreShapes\")\n\t\telse Broadcast(\"PassedReason for failure invalid!!!!\") end\n\tend\n\tBroadcast(\"GameBoard.CurrentScore: \"..GameBoard.CurrentScore)\n\tif GameBoard.CurrentScore==2 then\n\t\t--player has managed to make two sets that leave a non-valid set as the final three cards\n\t\tscene:TriggerServerEvent(\"LastCards\")\n\t\tWait(4)\n\t\tRestartGame()\n\t\tscene:TriggerServerEvent(\"Restart Game\")\n\tend--]]\n\tGameBoard.NumCardsActive=0\n\tfor LoopIndex,_ in pairs(GameBoard.CurrentCards) do\n\t\tGameBoard.CurrentCards[LoopIndex]:ClearSpellVisual(GameBoard.CurrentCards[LoopIndex].CurrentlyClicked)\n\t\tGameBoard.CurrentCards[LoopIndex].CurrentlyClicked=nil\n\t\tGameBoard.CurrentCards[LoopIndex]=nil\n\tend\n\tscene:PlaySoundKit(193452,true,scene:GetPosition())\t\n\tGameBoard.CurrentCards={}\n\tWait(2)\nend\n\nfunction ConstructDeck()\n\tlocal FormatString=\"Border[%s] Shape[%s] BorderCount[%s] ShapeCount[%s]\"\n\tif not GameBoard.RestoreDeck then\n\t\tGameBoard.Deck={}\n\t\tGameBoard.RestoreDeck={}\n\t\tlocal Borders={[1]=\"Cube\",[2]=\"Sphere\",[3]=\"Star\"}\n\t\tlocal Shapes={[1]=\"Triangle\",[2]=\"Circle\",[3]=\"Square\"}\n\t\tlocal BorderRemap={[\"Cube\"]=1,[\"Sphere\"]=2,[\"Star\"]=3}\n\t\tlocal ShapeRemap={[\"Triangle\"]=1,[\"Circle\"]=2,[\"Square\"]=3}\n\t\tlocal ShapeCounts,BorderCounts\n\t\tlocal BaseDeck={}\n\t\tlocal DictionaryDeck={}\n\t\tlocal Indices={}\n\t\tlocal LoopIndex\n\t\tfor LoopBorder=1,3 do\n\t\t\tfor LoopShape=1,3 do\n\t\t\t\tfor LoopShapeCount=1,3 ', 42423),
