(33474, '9.1 Broker Games - Matching - Functions', 'local NodeCoroutine\nfunction AddInteractCoroutine(...)\n\tscene:AddCoroutineWithParams(NodeCoroutine, ...)\nend\nNodeCoroutine = function(actor)\n\twhile (true) do\n\t\tactor:WaitRightClick()\n\t\tBroadcast(\"Clicked\")\n\t\tif InteractionAllowed() and actor.IsANode then\n\t\t\tDisableInteraction()\n\t\t\tAddClickedNode(actor)\n\t\t\tWait(.3)\n\t\t\tEnableInteraction()\n\t\telse\n\t\tend\n\tend\nend\n\nfunction AddClickedNode(PassedNode)\n\tlocal FormatString=\"Border[%s] Shape[%s] BorderCount[%s] ShapeCount[%s]\"\n\tBroadcast(\"Clicked on: \"..string.format(FormatString,PassedNode[\"Border\"],PassedNode[\"Shape\"],PassedNode[\"BorderCount\"],PassedNode[\"ShapeCount\"]))\n\tif PassedNode.CurrentlyClicked then\n\t\tscene:PlaySoundKit(193452,true,scene:GetPosition())\t\n\t\tBroadcast(\"Node Already Clicked, Clearing: \"..(PassedNode.Row*100+PassedNode.Col))\n\t\tAddActiveCard(PassedNode.Row*100+PassedNode.Col,nil)\n\t\tPassedNode:ClearSpellVisual(PassedNode.CurrentlyClicked)\n\t\tPassedNode.CurrentlyClicked=nil\n\telse\n\t\tscene:PlaySoundKit(193449,true,scene:GetPosition())\t\n\t\tPassedNode.CurrentlyClicked=PassedNode:PlaySpellStateVisual(NODE_STATE_VISUAL_SELECTED)\n\t\t--table.insert(GameBoard.CurrentCards,PassedNode)\n\t\tAddActiveCard(PassedNode.Row*100+PassedNode.Col,PassedNode)\n\t\t--GameBoard.CurrentCards[PassedNode.Row*100+PassedNode.Col]=PassedNode\n\t\tBroadcast(\"GameBoard[\"..PassedNode.Row*100+PassedNode.Col..\"]\")\n\t\tif not GameBoard.CurrentCards[PassedNode.Row*100+PassedNode.Col] then\n\t\t\tBroadcast(\"Failed to allocate GameBoard[\"..PassedNode.Row*100+PassedNode.Col..\"]\")\n\t\tend\n\t\tCheckCurrentCards()\n\tend\t\t\nend\n\nfunction AddActiveCard(PassedIndex,PassedNode)\n\tGameBoard.CurrentCards[PassedIndex]=PassedNode\n\tif PassedNode then\n\t\tif not GameBoard.NumCardsActive then GameBoard.NumCardsActive=0 end\n\t\tGameBoard.NumCardsActive=GameBoard.NumCardsActive+1\n\telse\n\t\tif not GameBoard.NumCardsActive then\n\t\telse\n\t\t\tGameBoard.NumCardsActive=GameBoard.NumCardsActive-1\n\t\tend\n\tend\nend\n\nfunction FailCurrentCards(PassedReason)\n\tBroadcast(\"Current set not valid!\")\n\tif PassedReason then\n\t\tBroadcast(\"Reason: \"..PassedReason)\n\tend\n\tGameBoard.NumCardsActive=0\n\tfor LoopIndex,_ in pairs(GameBoard.CurrentCards) do\n\t\tGameBoard.CurrentCards[LoopIndex]:ClearSpellVisual(GameBoard.CurrentCards[LoopIndex].CurrentlyClicked)\n\t\tGameBoard.CurrentCards[LoopIndex].CurrentlyClicked=nil\n\t\tGameBoard.CurrentCards[LoopIndex]=nil\n\tend\n\tscene:PlaySoundKit(193452,true,scene:GetPosition())\t\n\tGameBoard.CurrentCards={}\n\tWait(3)\nend\n\nfunction ConstructDeck()\n\tlocal FormatString=\"Border[%s] Shape[%s] BorderCount[%s] ShapeCount[%s]\"\n\tif not GameBoard.RestoreDeck then\n\t\tGameBoard.Deck={}\n\t\tGameBoard.RestoreDeck={}\n\t\tlocal Borders={[1]=\"Cube\",[2]=\"Sphere\",[3]=\"Star\"}\n\t\tlocal Shapes={[1]=\"Triangle\",[2]=\"Circle\",[3]=\"Square\"}\n\t\tlocal BorderRemap={[\"Cube\"]=1,[\"Sphere\"]=2,[\"Star\"]=3}\n\t\tlocal ShapeRemap={[\"Triangle\"]=1,[\"Circle\"]=2,[\"Square\"]=3}\n\t\tlocal ShapeCounts,BorderCounts\n\t\tlocal BaseDeck={}\n\t\tlocal DictionaryDeck={}\n\t\tlocal Indices={}\n\t\tlocal LoopIndex\n\t\tfor LoopBorder=1,3 do\n\t\t\tfor LoopShape=1,3 do\n\t\t\t\tfor LoopShapeCount=1,3 do\n\t\t\t\t\tfor LoopBorderCount=1,3 do\n\t\t\t\t\t\tLoopIndex=(LoopBorder*1000)+(LoopShape*100)+(LoopShapeCount*10)+LoopBorderCount\n\t\t\t\t\t\tBaseDeck[LoopIndex]={\n\t\t\t\t\t\t\t\t\t\t\t[\"Border\"]=Borders[LoopBorder],\n\t\t\t\t\t\t\t\t\t\t\t[\"Shape\"]=Shapes[LoopShape],\n\t\t\t\t\t\t\t\t\t\t\t[\"ShapeCount\"]=LoopShapeCount,\n\t\t\t\t\t\t\t\t\t\t\t[\"BorderCount\"]=LoopBorderCount\n\t\t\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\ttable.insert(Indices,LoopIndex)\n\t\t\t\t\t\tBroadcast(\"Inserted: \"..string.format(FormatString,Borders[LoopBorder],Shapes[LoopShape],LoopBorderCount,LoopShapeCount))\n\t\t\t\t\tend\n\t\t\t\tend\n\t\t\tend\t\