(33476, '[2] 9.1 Broker Games - Matching - Functions', 'MakeNewCard(PassedRow,PassedCol)\n\tGameBoard[PassedRow][PassedCol]=CreateNode(PassedRow,PassedCol)\n\tAddNodeVisual(GameBoard[PassedRow][PassedCol],table.remove(GameBoard.Deck))\nend\n\nfunction CheckCurrentCards()\n\tDisableInteraction()\n\tif GameBoard.NumCardsActive>2 then\n\t\t--Broadcast(\"Checking 3 cards!\")\n\t\tlocal ShouldScore=false\n\t\tlocal ValidBorders,ValidBorderCounts,ValidShapes,ValidShapeCounts=false,false,false,false\n\t\tlocal Cards={}\n\t\tfor Position,LoopCard in pairs(GameBoard.CurrentCards) do\n\t\t\t--Broadcast(\"Checking Position: \"..Position)\n\t\t\ttable.insert(Cards,LoopCard)\n\t\tend\n\t\tlocal AllSame,AllDifferent=false,false\n\t\tfor _,LoopAttribute in pairs({\"Border\",\"Shape\",\"BorderCount\",\"ShapeCount\"}) do\n\t\t\tif Cards[1][LoopAttribute]==Cards[2][LoopAttribute] and Cards[1][LoopAttribute]==Cards[3][LoopAttribute] then\n\t\t\t\tAllSame=true\n\t\t\telseif Cards[1][LoopAttribute]~=Cards[2][LoopAttribute] and Cards[1][LoopAttribute]~=Cards[3][LoopAttribute]\n\t\t\t\tand Cards[2][LoopAttribute]~=Cards[3][LoopAttribute] then\n\t\t\t\t\tAllDifferent=true\n\t\t\tend\n\t\t\tif not (AllSame or AllDifferent) then\n\t\t\t\tFailCurrentCards(LoopAttribute)\n\t\t\t\treturn\n\t\t\tend\n\t\t\tAllSame,AllDifferent=false,false\n\t\tend\n\t\tCompleteSet()\n\telse\n\t\tBroadcast(\"#CurrentCards: \"..GameBoard.NumCardsActive)\n\tend\n\tEnableInteraction()\nend\n\n\nfunction DespawnNode(PassedRow,PassedCol)\n\t--PassedIndex is still in the has form (Row*100+Col)\n\tlocal MappedNode=GameBoard[PassedRow][PassedCol]\n\twhile #MappedNode.SpellVisuals>0 do\n\t\tMappedNode:ClearSpellVisual(table.remove(MappedNode.SpellVisuals))\n\tend\n\tMappedNode:Despawn()\n\tGameBoard[PassedRow][PassedCol]=nil\nend\n\nfunction AddNodeVisual(PassedNode,PassedVisual)\n\tif PassedNode.SpellVisuals then\n\t\twhile #PassedNode.SpellVisuals>0 do\n\t\t\tPassedNode:ClearSpellVisual(table.remove(PassedNode.SpellVisuals))\n\t\tend\n\tend\n\tif PassedVisual then\n\t\tif PassedVisual[\"Border\"] and PassedVisual[\"BorderCount\"] then\n\t\t\tPassedNode[\"Border\"]=PassedVisual[\"Border\"]\n\t\t\tPassedNode[\"BorderCount\"]=PassedVisual[\"BorderCount\"]\n\t\t\ttable.insert(PassedNode.SpellVisuals,PassedNode:PlaySpellStateVisual(BORDER_VISUAL_LOOKUP_TABLE[PassedVisual[\"Border\"]][PassedVisual[\"BorderCount\"]]))\n\t\tend\n\t\tif PassedVisual[\"Shape\"] and PassedVisual[\"ShapeCount\"] then\n\t\t\tPassedNode[\"Shape\"]=PassedVisual[\"Shape\"]\n\t\t\tPassedNode[\"ShapeCount\"]=PassedVisual[\"ShapeCount\"]\n\t\t\ttable.insert(PassedNode.SpellVisuals,\n\t\t\t\t\tPassedNode:PlaySpellStateVisual(\n\t\t\t\t\t\tSHAPE_VISUAL_LOOKUP_TABLE[PassedVisual[\"Shape\"]][PassedVisual[\"ShapeCount\"]]\n\t\t\t\t\t)\n\t\t\t\t)\n\t\tend\n\telse\t\n\t\tPassedNode.SpellVisual=nil\n\tend\nend\n\nfunction ScrambleBoard()\n\tfor i=1,MaxDimensions[\"MaxRows\"] do\n\t\tfor j=1,MaxDimensions[\"MaxCols\"] do\n\t\t\tAddNodeVisual(GameBoard[i][j],table.remove(GameBoard.Deck))\n\t\tend\n\tend\nend\n\nfunction CreateNode(Row,Column,PassedValue)\n\n\tNodeCreateData.creatureDisplayID = NODE_CDI\n\tlocal nodeOffset = Vector:New(0,Column*COLUMN_WIDTH,Row*ROW_HEIGHTH)\n\tNodeCreateData.transform = Transform:New(BOARD_OFFSET+nodeOffset, scene:GetTransform().yaw, 0, 0)\n\tNodeCreateData.scale=NODE_SCALE\n\tNodeCreateData.interactible=true\n\t\n\tlocal thisNode = scene:SpawnActor(NodeCreateData)\n\tthisNode:SetInteractCursor(\"interact\", CursorRange.RangeFromPlayer, 20, nil)\n\tthisNode.selected = false\n\tthisNode.offset = nodeOffset\n\n\tthisNode.Row=Row\n\tthisNode.Col=Column\n\tthisNode.IsANode=true\n\t\n\tthisNode.SpellVisuals={}\n\t\n\tRideVehicleActor(thisNode, Player, 0, AttachmentPoint.Base,BOARD_OFFSET+nodeOffset+VEHICLE_OFFSET_Z,Vector:New(0,0,0))--scene:GetTransform().yaw\n\tAddInteractCoroutine(thisNode)\n\n\treturn thisNode\n\nend\n\nfunction CreateGameBoard(PassedLocation)\n\tDisableInteraction()\n\tlocal BoardCreateData = ActorCreateData:Default()\n\tBoardCreateData.groundSnap = true\n\tBoardCreateData.interactible = false\n\tBoardCreateData.selectable = false\n\t', 42423),
