(34982, '[1] 9.1 World Quest - Berlekamp (Tutorial) - Functions', '\tGameBoard.InteractionDisabled=true\nend\n\nfunction EnableInteraction()\n\tGameBoard.InteractionDisabled=nil\nend\n\nfunction InteractionAllowed()\n\tif not GameBoard then return false end\n\treturn not GameBoard.InteractionDisabled\nend\n\nfunction FailGame()\n\t--Broadcast(\"Game failed, clearing board\")\n\tDisableInteraction()\n\tClearBoard()\n\t--Broadcast(\"Restarting in 3...\")\n\tWait(1)\n\t--Broadcast(\"Restarting in 2..\")\n\tWait(1)\n\t--Broadcast(\"Restarting in 1.\")\n\tWait(1)\n\tRestartGame()\nend\n\nfunction MakeGameNodes()\n\tfor i=1,MaxDimensions[\"MaxRows\"] do\t\t\t\n\t\tGameBoard[i]={}\n\t\tfor j=1,MaxDimensions[\"MaxCols\"] do\n\t\t\tGameBoard[i][j]=CreateNode(i,j,-1)\n\t\tend\n\tend\nend\n\nfunction RestartGame()\n\t--Broadcast(\"Restarting Game\")\n\tDisableInteraction()\n\tClearBoard()\n\tMakeGameNodes()\n\tGameParameters[\"movesremaining\"]=GameParameters[\"maxmoves\"]\n\tScrambleBoard(GameBoard,GameParameters)\n\tDisplayBoard(GameParameters)\n\t\n\tEnableInteraction()\n\t\n\tDisplayOpening()\nend\n\nfunction FlipLights(PassedRowOrColumn,PassedName)\n\tif PassedName==\"Row\" then\n\t\tfor i=1,MaxDimensions[\"MaxCols\"] do\n\t\t\tGameBoard[PassedRowOrColumn][i].LitUp=-1*GameBoard[PassedRowOrColumn][i].LitUp\n\t\tend\n\telseif PassedName==\"Column\" then\n\t\t--Broadcast(\"Flipping Column[\"..PassedRowOrColumn..\"]\")\n\t\tfor i=1,MaxDimensions[\"MaxRows\"] do\n\t\t\tGameBoard[i][PassedRowOrColumn].LitUp=-1*GameBoard[i][PassedRowOrColumn].LitUp\n\t\tend\n\telse\n\t\tBroadcast(\"Invalid Row Or Column Name Passed Into FlipLights: \"..tostring(PassedName))\n\tend\n\tGameParameters[\"movesremaining\"]=GameParameters[\"movesremaining\"]-1\n\tif GameParameters[\"movesremaining\"]<=0 and not GameIsFinished() then\n\t\tscene:TriggerServerEvent(\"Failure\")\n\t\tWait(3)\n\t\tFailGame()\n\telse\n\t\t--Broadcast(\"Moves remaining: \"..GameParameters[\"movesremaining\"])\n\tend\nend\n\n\nlocal NodeCoroutine\nfunction AddInteractCoroutine(...)\n\tscene:AddCoroutineWithParams(NodeCoroutine, ...)\nend\nNodeCoroutine = function(actor)\n\twhile (true) do\n\t\tactor:WaitRightClick()\n\t\tif InteractionAllowed() then\n\t\t\tscene:PlaySoundKit(193443,true,scene:GetPosition())\t\n\t\t\tDisableInteraction()\n\t\t\t--Broadcast(\"Flipping Lights of \"..actor.RowOrColumnName..\"[\"..actor.MyRowOrColumn..\"]\")\n\t\t\tFlipLights(actor.MyRowOrColumn,actor.RowOrColumnName)\n\t\t\tlocal DisplayParameters={[\"debug\"]=nil}\n\t\t\tDisplayBoard(DisplayParameters)\n\t\t\tEnableInteraction()\n\t\telse\n\t\tend\n\tend\nend\n\n\nfunction CreateNode(Row,Column,PassedValue)\n\n\tNodeCreateData.creatureDisplayID = NODE_CDI\n\tlocal nodeOffset = Vector:New(0,Column*COLUMN_WIDTH,Row*ROW_HEIGHTH)\n\tNodeCreateData.transform = Transform:New(BOARD_OFFSET+nodeOffset, scene:GetTransform().yaw, 0, 0)\n\tNodeCreateData.scale=NODE_SCALE\n\tNodeCreateData.interactible=false\n\t\n\tlocal thisNode = scene:SpawnActor(NodeCreateData)\n\t--thisNode:SetInteractCursor(\"interact\", CursorRange.RangeFromPlayer, 20, nil)\n\tthisNode.selected = false\n\tthisNode.offset = nodeOffset\n\tthisNode.LitUp = PassedValue\n\tthisNode.SpellVisualName=NODE_STATE_VISUAL_DARK\n\tthisNode.SpellVisual = nil\n\t\n\tRideVehicleActor(thisNode, Player, 0, AttachmentPoint.Base,BOARD_OFFSET+nodeOffset+VEHICLE_OFFSET_Z,Vector:New(0,0,0))--scene:GetTransform().yaw\n\treturn thisNode\n\nend\n\nfunction CreateGameBoard(PassedLocation)\n\tDisableInteraction()\n\t\n\tlocal BoardCreateData = ActorCreateData:Default()\n\tBoardCreateData.groundSnap = true\n\tBoardCreateData.interactible = false\n\tBoardCreateData.selectable = false\n\tBoardCreateData.floatingTooltip = false\n\tBoardCreateData.scale = BOARD_SCALE\n\tBoardCreateData.creatureDisplayID = BOARD_CDI\n\tBoardCreateData.offset=Vector:New(0,0,0)\n\t\n\tlocal MyBoard = scene:SpawnActor(BoardCreateData)\n\tMyBoard.selected = false\n\ttable.insert(SpellVisualsToClear,{MyBoard,MyBoard:PlaySpellStateVisual(BOARD_STATE_VISUAL)})\n\t\t\n\tRideVehicleActor(MyBoard, Player, 0, ', 42423),
(30701, '[2] 9.1 World Quest - Berlekamp - Functions', 'on the outside edges..\n\tfor i=1,MaxDimensions[\"MaxRows\"] do\n\t\tCreateInteract(i,-1)--yes, -1 looks weird.  It\'s ok.\n\tend\n\tfor i=1,MaxDimensions[\"MaxCols\"] do\n\t\tCreateInteract(-1,i)\n\tend\n\t\n\tfor i=1,MaxDimensions[\"MaxRows\"] do\t\t\t\n\t\tGameBoard[i]={}\n\t\tfor j=1,MaxDimensions[\"MaxCols\"] do\n\t\t\tGameBoard[i][j]=CreateNode(i,j,-1)\n\t\tend\n\tend\n\t\n\tGameParameters[\"movesremaining\"]=GameParameters[\"maxmoves\"]\n\t\n\tScrambleBoard(GameBoard,GameParameters)\n\t\n\tDisplayBoard(GameParameters)\n\t\n\tDisplayOpening()\n\t\n\tEnableInteraction()\nend\n\nfunction DisplayBoard(PassedParameters)\n\tif not GameBoard then\n\t\tBroadcast(\"[CS30435] No GameBoard to display!\")\n\t\treturn\n\tend\n\tlocal DisplayRow\n\tfor i=1,MaxDimensions[\"MaxRows\"] do\n\t\tDisplayRow=\"Row[\"..i..\"]\"\n\t\tfor j=1,MaxDimensions[\"MaxCols\"] do\n\t\t\tif GameBoard and GameBoard[i] and GameBoard[i][j] then\n\t\t\t\tif GameBoard[i][j].LitUp > 0 then\n\t\t\t\t\t--Show Lit up Visual\n\t\t\t\t\tManageNodeVisual(GameBoard[i][j],NODE_STATE_VISUAL_LITUP)\n\t\t\t\telseif GameBoard[i][j].LitUp < 0 then\n\t\t\t\t\t--Show Not Lit Up\n\t\t\t\t\tManageNodeVisual(GameBoard[i][j],NODE_STATE_VISUAL_DARK)\n\t\t\t\tend\n\t\t\t\tDisplayRow=DisplayRow..GameBoard[i][j].LitUp..\" \"\t\t\n\t\t\telse\n\t\t\tend\n\t\tend\n\t\tif PassedParameters and PassedParameters[\"debug\"]==true then\n\t\t\tBroadcast(DisplayRow)\n\t\tend\n\tend\n\t\nend\n\nfunction ScrambleBoard(PassedBoard,PassedParameters)\n\tif not PassedParameters then \n\t\tPassedParameters={[\"complexity\"]=0,[\"allowduplicates\"]=nil,[\"allowrepeats\"]=false}\n\tend\n\n\t--Build table of all scrambling moves\n\tlocal ScramblingMoves={}\n\tfor i=1,MaxDimensions[\"MaxRows\"] do\n\t\ttable.insert(ScramblingMoves,{[\"target\"]=\"column\",\t[\"value\"]=i})\n\tend\n\tfor i=1,MaxDimensions[\"MaxCols\"] do\n\t\ttable.insert(ScramblingMoves,{[\"target\"]=\"row\",\t[\"value\"]=i})\n\tend\n\t\n\t\n\tlocal LoopMove\n\tfor i=1,PassedParameters[\"complexity\"] do\n\t\tif i==1 or PassedParameters[\"allowrepeats\"] then\n\t\t\tLoopMove=table.remove(ScramblingMoves,math.random(1,#ScramblingMoves))\n\t\telse\n\t\t\tLoopMove=table.remove(ScramblingMoves,math.random(1,#ScramblingMoves-1))--Don\'t use the end of the list, that was the last move\n\t\tend\n\t\tif PassedParameters[\"debug\"] then\n\t\t\tBroadcast(\"Move[\"..i..\"]: \"..LoopMove[\"target\"]..\": \"..LoopMove[\"value\"])\n\t\tend\n\t\tif LoopMove[\"target\"]==\"row\" then\n\t\t\tfor column=1,MaxDimensions[\"MaxCols\"] do\n\t\t\t\tPassedBoard[LoopMove[\"value\"]][column].LitUp=-1*PassedBoard[LoopMove[\"value\"]][column].LitUp\n\t\t\tend\n\t\telseif LoopMove[\"target\"]==\"column\" then\n\t\t\tfor row=1,MaxDimensions[\"MaxRows\"] do\n\t\t\t\tPassedBoard[row][LoopMove[\"value\"]].LitUp=-1*PassedBoard[row][LoopMove[\"value\"]].LitUp\n\t\t\tend\n\t\tend\n\t\tif PassedParameters[\"allowduplicates\"] then\n\t\t\ttable.insert(ScramblingMoves,LoopMove)\n\t\tend\n\tend\nend\n\nfunction GameIsFinished()\n\tif not GameBoard then return false end\n\tfor i=1,MaxDimensions[\"MaxRows\"] do\n\t\tfor j=1,MaxDimensions[\"MaxCols\"] do\n\t\t\tif GameBoard then\n\t\t\t\tif GameBoard[i] then\n\t\t\t\t\tif GameBoard[i][j] then \n\t\t\t\t\t\tif GameBoard[i][j].LitUp==1 then return false end\n\t\t\t\t\telse\n\t\t\t\t\t\t--Broadcast(\"No entry for Node[\"..i..\"][\"..j..\"]\")\n\t\t\t\t\t\treturn false\n\t\t\t\t\tend\n\t\t\t\telse\n\t\t\t\t\t--Broadcast(\"No entry for Row[\"..i..\"]\")\n\t\t\t\t\treturn false\n\t\t\t\tend\n\t\t\telse\n\t\t\t\t--Broadcast(\"No GameBoard found?\")\n\t\t\t\treturn false\n\t\t\tend\n\t\tend\n\tend\n\treturn true\t\t\t\nend', 42423),
(30436, '[1] 9.1 World Quest - Berlekamp - Functions', '\tClearBoard()\n\tBroadcast(\"Restarting in 3...\")\n\tWait(1)\n\tBroadcast(\"Restarting in 2..\")\n\tWait(1)\n\tBroadcast(\"Restarting in 1.\")\n\tWait(1)\n\tRestartGame()\nend\n\nfunction MakeGameNodes()\n\tfor i=1,MaxDimensions[\"MaxRows\"] do\t\t\t\n\t\tGameBoard[i]={}\n\t\tfor j=1,MaxDimensions[\"MaxCols\"] do \n\t\t\tGameBoard[i][j]=CreateNode(i,j,-1)\n\t\tend\n\tend\nend\n\nfunction RestartGame()\n\tBroadcast(\"Restarting Game\")\n\tDisableInteraction()\n\tClearBoard()\n\tMakeGameNodes()\n\tGameParameters[\"movesremaining\"]=GameParameters[\"maxmoves\"]\n\tScrambleBoard(GameBoard,GameParameters)\n\tDisplayBoard(GameParameters)\n\tDisplayOpening()\n\tEnableInteraction()\nend\n\nfunction FlipLights(PassedRowOrColumn,PassedName)\n\tif PassedName==\"Row\" then\n\t\tfor i=1,MaxDimensions[\"MaxCols\"] do\n\t\t\tGameBoard[PassedRowOrColumn][i].LitUp=-1*GameBoard[PassedRowOrColumn][i].LitUp\n\t\tend\n\telseif PassedName==\"Column\" then\n\t\t--Broadcast(\"Flipping Column[\"..PassedRowOrColumn..\"]\")\n\t\tfor i=1,MaxDimensions[\"MaxRows\"] do\n\t\t\tGameBoard[i][PassedRowOrColumn].LitUp=-1*GameBoard[i][PassedRowOrColumn].LitUp\n\t\tend\n\telse\n\t\tBroadcast(\"Invalid Row Or Column Name Passed Into FlipLights: \"..tostring(PassedName))\n\tend\n\tGameParameters[\"movesremaining\"]=GameParameters[\"movesremaining\"]-1\n\tif GameParameters[\"movesremaining\"]<=0 and not GameIsFinished() then\n\t\tFailGame()\n\telse\n\t\tBroadcast(\"Moves remaining: \"..GameParameters[\"movesremaining\"])\n\tend\nend\n\n\nlocal NodeCoroutine\nfunction AddInteractCoroutine(...)\n\tscene:AddCoroutineWithParams(NodeCoroutine, ...)\nend\nNodeCoroutine = function(actor)\n\twhile (true) do\n\t\tactor:WaitRightClick()\n\t\tif InteractionAllowed() then\n\t\t\tscene:PlaySoundKit(193443,true,scene:GetPosition())\t\n\t\t\tDisableInteraction()\n\t\t\t--Broadcast(\"Flipping Lights of \"..actor.RowOrColumnName..\"[\"..actor.MyRowOrColumn..\"]\")\n\t\t\tFlipLights(actor.MyRowOrColumn,actor.RowOrColumnName)\n\t\t\tlocal DisplayParameters={[\"debug\"]=nil}\n\t\t\tDisplayBoard(DisplayParameters)\n\t\t\tEnableInteraction()\n\t\telse\n\t\tend\n\tend\nend\n\n\nfunction CreateNode(Row,Column,PassedValue)\n\n\tNodeCreateData.creatureDisplayID = NODE_CDI\n\tlocal nodeOffset = Vector:New(0,Column*COLUMN_WIDTH,Row*ROW_HEIGHTH)\n\tNodeCreateData.transform = Transform:New(BOARD_OFFSET+nodeOffset, scene:GetTransform().yaw, 0, 0)\n\tNodeCreateData.scale=NODE_SCALE\n\tNodeCreateData.interactible=false\n\t\n\tlocal thisNode = scene:SpawnActor(NodeCreateData)\n\t--thisNode:SetInteractCursor(\"interact\", CursorRange.RangeFromPlayer, 20, nil)\n\tthisNode.selected = false\n\tthisNode.offset = nodeOffset\n\tthisNode.LitUp = PassedValue\n\tthisNode.SpellVisualName=NODE_STATE_VISUAL_DARK\n\tthisNode.SpellVisual = nil\n\t\n\tRideVehicleActor(thisNode, Player, 0, AttachmentPoint.Base,BOARD_OFFSET+nodeOffset+VEHICLE_OFFSET_Z,Vector:New(0,0,0))--scene:GetTransform().yaw\n\treturn thisNode\n\nend\n\nfunction DisplayOpening()\n\tscene:PlaySoundKit(193446,true,scene:GetPosition())\t\n\tBroadcast(\"Turn OFF all Lights within \"..GameParameters[\"movesremaining\"]..\" moves.\")\n\tWait(1)\n\tBroadcast(\"Click on one of the Progenitor runes to flip the squares of its adjacent row or column.\")\n\tWait(1)\n\tBroadcast(\"Good luck!\")\nend\n\nfunction CreateGameBoard(PassedLocation)\n\tDisableInteraction()\n\tlocal BoardCreateData = ActorCreateData:Default()\n\tBoardCreateData.groundSnap = true\n\tBoardCreateData.interactible = false\n\tBoardCreateData.selectable = false\n\tBoardCreateData.floatingTooltip = false\n\tBoardCreateData.scale = BOARD_SCALE\n\tBoardCreateData.creatureDisplayID = BOARD_CDI\n\tBoardCreateData.offset=Vector:New(0,0,0)\n\t\n\tlocal MyBoard = scene:SpawnActor(BoardCreateData)\n\tMyBoard.selected = false\n\ttable.insert(SpellVisualsToClear,{MyBoard,MyBoard:PlaySpellStateVisual(BOARD_STATE_VISUAL)})\n\t\t\n\tRideVehicleActor(MyBoard, Player, 0, AttachmentPoint.Base,BOARD_OFFSET+VEHICLE_OFFSET_Z,Vector:New(0,0,0))--scene:GetTransform().yaw\n\t--Need to place interacts ', 42423),
(34266, '9.2 ZM - Puzzle - Match 3 Game - Action', 'PATH_ID_CAMERA_START = 30984\nPATH_ID_CAMERA_END = 30986\n\nscene:SetFadeRegion(50000, true)\n\nlocal gemCam = 804\nSetCameraFollowPath( gemCam, 1, PATH_ID_CAMERA_START, PATH_ID_CAMERA_END, 100000)\nlocal background = CreateBackground()\n--Broadcast(\"BACKGROUND\")\n--Broadcast(background)\n--Broadcast(\"BACKGROUND\")\n--Broadcast(background.isBackground)\n\n--INIT GEMS------------------------------------------------------------\nfor i=1, COLUMNS do\n\tgems[i] = {}\n\tfor j=1, ROWS do\n\t\tCreateGem(i, j, 0)\n\tend\nend\n\n--CHECK ONCE------------------------------------------------------------\nCheckForMatches()\n\n\nwhile (true) do\n\tWait(300)\nend', 42423),
(34265, '9.2 ZM - Puzzle - Match 3 Game - Functions C', 'function CreateBackground()\n\t\n\tbackgroundCreateData = ActorCreateData:Default()\n\tbackgroundCreateData.groundSnap = false\n\tbackgroundCreateData.interactible = false\n\tbackgroundCreateData.selectable = false\n\tbackgroundCreateData.floatingTooltip = false\n\tbackgroundCreateData.scale = SCALE_BACKGROUND\n\tbackgroundCreateData.creatureID = BACKGROUND_CREATURE\n\tbackgroundCreateData.disableUpdates = false\n\n\tbackgroundCreateData.transform = Transform:New(sceneOffset, 0, 90, 0)\n\n\tlocal background = scene:SpawnActor(backgroundCreateData)\n\t--background.selected = false\n\t--background.offset = nodeOffset\n\t--background.myVisual = nil\n\tbackground.isBackground = true\n\n--\tbackground:MoveToAbs(playerDisplay:GetPosition()+sceneOffset, 0)\n\tbackground:MoveToAbs(backgroundOffset, 0)\n\treturn background\n\nend', 42423),
(34264, '9.2 ZM - Puzzle - Match 3 Game - Functions B', 'function GemDelete(gem)\n\t--Grant deletion credit\n\t--local gemcolor = scene:GetWorldState(17663)\n\t--if gem.type == gemcolor then\n\t\t--scene:TriggerServerEvent(\"win_toast\")\n\t\t--scene:TriggerServerEvent(\"win\")\n\t--end\n\n\tlocal row = gem.row\n\tlocal col = gem.col\n\tif gem.deleted==false then\n\t\tgem.deleted=true\n\t\tfor j=1,row-1 do\n\t\t\tif gems[col][j]~= nil then\n\t\t\t\t--(\"Incrementing rows to fall\")\n\t\t\t\tgems[col][j].rowsToFall = gems[col][j].rowsToFall + 1\n\t\t\tend\n\t\tend\n\tend\nend \n\nfunction CreateGem(column, row, height)\n\t--Broadcast(\"Creating gem at col \"..column..\", row \"..row..\", height \"..height)\n\n\tlocal type = math.random(#DISPLAY)\n\tgemCreateData.creatureDisplayID = DISPLAY[type]\n\n\tflyerDrop = DROPS[type]\n\n\tlocal gemOffset = Vector:New(0, column*GEM_SPACING, (height-row)*GEM_SPACING - flyerDrop)\n\tgemCreateData.transform = Transform:New(sceneOffset+gemOffset, playerDisplay:GetTransform().yaw+180, 0, 0)\n\n\tgems[column][row] = scene:SpawnActor(gemCreateData)\n\tgems[column][row]:SetInteractCursor(\"interact\", CursorRange.RangeFromPlayer, 20, nil)\n\tgems[column][row].col = column\n\tgems[column][row].row = row\n\tgems[column][row].selected = false\n\tgems[column][row].myVisual = nil\n\tgems[column][row].type = type\n\tgems[column][row].deleted = false\n\tgems[column][row].rowsToFall = 0\n\tgems[column][row].height = height\n\tgems[column][row].dying = false\n\t--gems[column][row]:SetFacingToTarget(playerDisplay, Vector:New())\n\n\t--RideVehicleActor(gems[column][row], playerDisplay, 0, AttachmentPoint.Base, sceneOffset+gemOffset, Vector:New(playerDisplay:GetTransform().yaw+180, 0, 0))\n\tgems[column][row]:MoveToAbs(playerDisplay:GetPosition()+sceneOffset+gemOffset, 0)\n\tAddGemCoroutine(gems[column][row])\n\treturn gems[column][row]\n\nend\n\nfunction FaceForward()\n\tfor i=1, COLUMNS do\n\t\tfor j=1, ROWS do\n\t\t\tif gems[i][j]~= nil then\n\t\t\t\t--gems[i][j]:SetFacingToTarget(playerDisplay, Vector:New())\n\t\t\t\tgems[i][j]:StopAnimKit(FALL_ANIM_KIT)\n\t\t\t\tgems[i][j].isSelected = false\n\t\t\tend\n\t\tend\n\tend\nend\n\nlocal DeathCoroutine\nfunction AddDeathCoroutine(...)\n\tscene:AddCoroutineWithParams(DeathCoroutine, ...)\nend\nDeathCoroutine = function(actor)\n\tactor.dying = true\n\tactor.row = 1000000\n\tactor.col = 1000000\n\t--actor:SetFacingToTarget(playerDisplay, Vector:New())\n\t--actor:PlayLoopingAnimKit(4170)\n\tactor:PlaySpellCastVisual(EXPLOSION_CAST)\n\tlocal newPos = actor:GetPosition() + deathVector\n\tactor:MoveToAbs(newPos, DEATH_TIME)\n\tFadeOut(actor, DEATH_TIME)\n\tWait(DEATH_TIME)\n\tactor:Despawn()\nend  \n\n\nfunction PrettyNumberString( number )\n\tlocal string = tostring(number)\n\tlocal millions = string.sub(string, 1, string.len(string)-6)\n\tlocal thousands = string.sub(string, -6, -4)\n\tlocal singles = string.sub(string, -3)\n\tif number<1000 then\n\t\tstring = singles\n\telseif number<1000000 then\n\t\tstring = thousands..\",\"..singles\n\telse\n\t\tstring = millions..\",\"..thousands..\",\"..singles\n\tend\n\treturn string\nend\n\n\nfunction ShowScore(actor, amount)\n\tscore = score + amount\n\tlocal type = WorldText.Critical\n\t--actor:AddCustomWorldText( type, true, Color:New(250,100,250), \"?\" ) \n\t--Broadcast(\"Score:\"..score)\n\t--Win check\n\tif score >= UNLOCK_SCORE_THRESHOLD then\n\t\tscene:TriggerServerEvent(\"win_toast\")\n\t\tscene:TriggerServerEvent(\"win\")\n\tend\nend', 42423),
(34263, '[1] 9.2 ZM - Puzzle - Match 3 Game - Functions A', 'matchCount=0\n\t\t\t\tend\n\t\t\t\tif matchCount==2 then\n\t\t\t\t\t--Broadcast(\"adding to delete table\")\n\t\t\t\t\tGemDelete(gems[i][j-2])\n\t\t\t\t\tGemDelete(gems[i][j-1])\n\t\t\t\t\tGemDelete(gems[i][j])\n\t\t\t\t\tShowScore(gems[i][j-1], SCORE_MATCH)\n\t\t\t\t\tmatchFound = true\n\t\t\t\telseif matchCount>2 then\n\t\t\t\t\tGemDelete(gems[i][j])\n\t\t\t\t\tShowScore(gems[i][j], SCORE_ADDITIONAL)\n\t\t\t\t\tmatchFound = true\n\t\t\t\tend\n--\t\t\t\tif matchCount >= 2 then\n--\t\t\t\t\tif thisType == gemcolor then\n--\t\t\t\t\t\tscene:TriggerServerEvent(\"win\")\n--\t\t\t\t\tend\n--\t\t\t\tend\n\t\t\tend\n\t\tend\n\t\tcurrentType = 0\n\t\tmatchCount = 0\n\tend\n\tcurrentType = 0\n\tmatchCount = 0\n\n\t--print(\"easy\")\n\n\t--Check horizontal matches\n\tfor j=1, ROWS do\n\t\tfor i=1, COLUMNS do\n\t\t\tif gems[i][j]~= nil then\n\t\t\t\tlocal thisType = gems[i][j].type\n\t\t\t\tif thisType==currentType then\n\t\t\t\t\tmatchCount = matchCount+1\n\t\t\t\telse\n\t\t\t\t\tcurrentType=thisType\n\t\t\t\t\tmatchCount=0\n\t\t\t\tend\n\t\t\t\tif matchCount==2 then\n\t\t\t\t\tGemDelete(gems[i-2][j])\n\t\t\t\t\tGemDelete(gems[i-1][j])\n\t\t\t\t\tGemDelete(gems[i][j])\n\t\t\t\t\tShowScore(gems[i-1][j], SCORE_MATCH)\n\t\t\t\t\tmatchFound = true\t\n\t\t\t\telseif matchCount>2 then\n\t\t\t\t\tGemDelete(gems[i][j])\n\t\t\t\t\tShowScore(gems[i][j], SCORE_ADDITIONAL)\n\t\t\t\t\tmatchFound = true\n\t\t\t\tend\n--\t\t\t\tif matchCount >= 2 then\n--\t\t\t\t\tif thisType == gemcolor then\n--\t\t\t\t\t\tscene:TriggerServerEvent(\"win\")\n--\t\t\t\t\tend\n--\t\t\t\tend\n\t\t\tend\n\t\tend\n\t\tcurrentType = 0\n\t\tmatchCount = 0\n\tend\n\n\t\n\t--Delete matched actors\n\tfor i=1, COLUMNS do\n\t\tfor j=1, ROWS do\n\t\t\tif gems[i][j]~= nil then\n\t\t\t\tif gems[i][j].deleted==true then\n\t\t\t\t\tgaps[i] = gaps[i]+1\n\t\t\t\t\tAddDeathCoroutine(gems[i][j])\n\t\t\t\t\t--Broadcast(gems[i][j])\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\n\t--Set new row values\n\tfor i=1, COLUMNS do\n\t\tfor j=ROWS, 1, -1 do\n\t\t\tif gems[i][j]~= nil then\n\t\t\t\tlocal rowsToFall = gems[i][j].rowsToFall\n\t\t\t\tif (rowsToFall>0) then\n\t\t\t\t\tgems[i][j].row = gems[i][j].row+rowsToFall\n\t\t\t\t\tgems[i][j+rowsToFall] = gems[i][j]\n\t\t\t\t\tgems[i][j] = nil\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\n\n\t--Add replacements\n\tfor i=1, COLUMNS do\n\t\tfor j=1, gaps[i] do\n\t\t\tlocal type = math.random(#DISPLAY)\n\t\t\tlocal newGem = CreateGem(i,j,gaps[i])\n\t\tend\n\tend\n\n\t--Make them fall\n\tlocal maxFalls = 0\n\tfor i=1, COLUMNS do\n\t\tfor j=ROWS, 1, -1 do\n\t\t\tif gems[i][j]~= nil then\n\t\t\t\tlocal rowsToFall = gems[i][j].rowsToFall\n\t\t\t\tlocal height = gems[i][j].height\n\t\t\t\tif (rowsToFall+height) > 0 then\n\t\t\t\t\t--Broadcast(\"Falling \"..rowsToFall..\"+\"..height..\" rows\")\n\t\t\t\t\tif (rowsToFall+height) > maxFalls then\n\t\t\t\t\t\tmaxFalls = rowsToFall+height\n\t\t\t\t\tend\n\t\t\t\t\tlocal myFallVector = (rowsToFall+height) * fallVector\n\t\t\t\t\tlocal newPos = gems[i][j]:GetPosition() + myFallVector\n\t\t\t\t\t--gems[i][j]:MoveToAbs(newPos, FALL_TIME * (rowsToFall+height))\n\t\t\t\t\tlocal type = gems[i][j].type\n\t\t\t\t\tflyerDrop = DROPS[type]\n\n\t\t\t\t\tlocal gemOffset = Vector:New(0, i*GEM_SPACING, (-j)*GEM_SPACING - flyerDrop)\n\t\t\t\t\t--RideVehicleActor(gems[i][j], playerDisplay, FALL_TIME * (rowsToFall+height), AttachmentPoint.Base, sceneOffset+gemOffset, Vector:New(scene:GetTransform().yaw+180, 0, 0))\n\t\t\t\t\tgems[i][j]:MoveToAbs(playerDisplay:GetPosition() + sceneOffset+gemOffset, FALL_TIME * (rowsToFall+height))\n\t\t\t\t\tgems[i][j].rowsToFall = 0\n\t\t\t\t\tgems[i][j].height = 0\n\t\t\t\t\tgems[i][j]:PlayLoopingAnimKit(9091)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\n\tWait(FALL_TIME*maxFalls)\n\tgaps = {}\n\tFaceForward()\n\t\n\tif matchFound==true then\n\t\tCheckForMatches(false)\n\telse\n\t\tif firstMove==true then\n\t\t\tSwitch(lastSwitchedA, lastSwitchedB, true)\n\t\tend\n\t\tfalling = false\n\tend\n\t\nend\n\n', 42423),
(34262, '9.2 ZM - Puzzle - Match 3 Game - Functions A', '\n--FUNCTIONS------------------------------------------------------------\n\n\nlocal GemCoroutine\nfunction AddGemCoroutine(...)\n\tscene:AddCoroutineWithParams(GemCoroutine, ...)\nend\nGemCoroutine = function(actor)\n\twhile (true) do\n\t\tactor:WaitRightClick()\n\t\tif (not switching and not falling and actor.col<=COLUMNS) then\n\t\t\t--Actor currently selected, de-select him\n\t\t\t--Broadcast(\"Clicking row \"..actor.row..\", col \"..actor.col)\n\t\t\tif (actor.isSelected==true) then\n\t\t\t\tactor.isSelected = false\n\t\t\t\tselected = nil\n\t\t\t\tactor:ClearSpellVisual( actor.myVisual)                    \n\t\t\t\tactor:PlaySpellCastVisual(CLICK_CAST_B)\n\t\t\telse\n\t\t\t\tif (selected ~= nil) then\n\t\t\t\t\tlocal selectDeltaRow = math.abs(selected.row-actor.row)\n\t\t\t\t\tlocal selectDeltaCol = math.abs(selected.col-actor.col)\n\t\t\t\t\tselected.isSelected = false\n\t\t\t\t\tselected:ClearSpellVisual( selected.myVisual)                    \n\t\t\t\t\tif (selectDeltaRow+selectDeltaCol==1 and selected.dying==false) then\n\t\t\t\t\t\tactor:PlaySpellCastVisual(CLICK_CAST_B)\n\t\t\t\t\t\tSwitch(actor, selected, false)\n\t\t\t\t\telse\n\t\t\t\t\t\tactor.isSelected = true\n\t\t\t\t\t\tactor.myVisual = actor:PlaySpellStateVisual(SELECTED_STATE)\n\t\t\t\t\t\tselected = actor\n\t\t\t\t\t\tactor:PlaySpellCastVisual(CLICK_CAST_A)\n\t\t\t\t\tend\n\t\t\t\telse\n\t\t\t\t\tactor.isSelected = true\n\t\t\t\t\tactor.myVisual = actor:PlaySpellStateVisual(SELECTED_STATE)\n\t\t\t\t\tselected = actor\n\t\t\t\t\tactor:PlaySpellCastVisual(CLICK_CAST_A)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\nend \n\nfunction Switch(actorA, actorB, switchBack)\n\t--Broadcast(\"SWITCHING with column \"..actorB.row..\", column \"..actorB.col)\n\tswitching = true\n\tlocal posA = actorA:GetPosition()\n\tlocal posB = actorB:GetPosition()\n\tlocal distance = Vector.Magnitude(posA-posB)\n\tif distance<2*GEM_SPACING then\n\n\t\tlocal rowA,colA = actorA.row, actorA.col\n\t\tlocal rowB,colB = actorB.row, actorB.col\n\t\tlocal typeA,typeB = actorA.type, actorB.type\n\t\tlocal flyerDropA, flyerDropB = 0, 0\n\t\tflyerDropA = DROPS[typeA]\n\t\tflyerDropB = DROPS[typeB]\n\t\t\n\t\t--actorA:MoveToAbs(posB, MOVE_TIME)\n\t\t--actorB:MoveToAbs(posA, MOVE_TIME)\n\t\tlocal gemOffsetA = Vector:New(0, colA*GEM_SPACING, (-rowA)*GEM_SPACING-flyerDropB)\n\t\tlocal gemOffsetB = Vector:New(0, colB*GEM_SPACING, (-rowB)*GEM_SPACING-flyerDropA)\n\t\t--RideVehicleActor(actorA, playerDisplay, MOVE_TIME, AttachmentPoint.Base, sceneOffset+gemOffsetB, Vector:New(playerDisplay:GetTransform().yaw+180, 0, 0))\n\t\t--RideVehicleActor(actorB, playerDisplay, MOVE_TIME, AttachmentPoint.Base, sceneOffset+gemOffsetA, Vector:New(playerDisplay:GetTransform().yaw+180, 0, 0))\n\t\tactorA:MoveToAbs(posB, MOVE_TIME)\n\t\tactorB:MoveToAbs(posA, MOVE_TIME)\n\n\t\tif switchBack then\n\t\t\tactorA:PlaySpellCastVisual(SLIDE_CAST_B)\n\t\telse\n\t\t\tactorA:PlaySpellCastVisual(SLIDE_CAST_A)\n\t\tend\n\t\tlastSwitchedA = actorA\n\t\tlastSwitchedB = actorB\n\t\tWait(MOVE_TIME)\n\t\tgems[colA][rowA] = actorB\n\t\tgems[colB][rowB] = actorA\n\t\tactorA.row = rowB\n\t\tactorA.col = colB\n\t\tactorB.row = rowA\n\t\tactorB.col = colA\n\t\t--actorA:SetFacing(sceneFacing)\n\t\t--actorB:SetFacing(sceneFacing)\n\t\tfalling = true\n\t\tswitching = false\n\t\tif switchBack==false then\n\t\t\tselected = nil\n\t\t\tCheckForMatches(true)\n\t\tend\n\tend\nend\n\n\nfunction CheckForMatches(firstMove)\n\tlocal matchFound = false\n\tlocal maxGaps = 0\n\tlocal gaps = {}\n\tfor i=1, COLUMNS do\n\t\ttable.insert(gaps, 0)\n\tend\n\n\tlocal gemcolor = scene:GetWorldState(17663)\n\t\n\t--Broadcast(\"=========================================================\")\n\tlocal matchTable = {}\n\tlocal currentType = 0\n\tlocal matchCount = 0\n\t\n\t--Check vertical matches\n\tfor i=1, COLUMNS do\n\t\tfor j=1, ROWS do\n\t\t\tif gems[i][j]~= nil then\n\t\t\t\tlocal thisType = gems[i][j].type\n\t\t\t\tif thisType==currentType then\n\t\t\t\t\tmatchCount = matchCount+1\n\t\t\t\t\t--Broadcast(\"match\")\n\t\t\t\telse\n\t\t\t\t\t--Broadcast(\"no match, current/this: \"..currentType..\"/\"..thisType)\n\t\t\t\t\tcurrentType=thisType\n\t\t\t\t\t', 42423),
(34261, '9.2 ZM - Puzzle - Match 3 Game - Hard - Globals', 'scene:SetRelativeCoords(true)\nplayerDisplay = scene:GetActivePlayerDisplay()\n\nGAME_TIME = 300\nGAME_DISTANCE = 25\nSCALE_GEM = .1\nGEM_SPACING = 0.2\nFLYER_HEIGHT = 0.08\nROWS = 9\nCOLUMNS = 12\nGAME_HEIGHT = 3\nGAME_FRONT = 2\nSELECTED_STATE = 110872\nEXPLOSION_CAST = 110873\nCLICK_CAST_A = 71257\nCLICK_CAST_B = 71258\nSLIDE_CAST_A = 71259\nSLIDE_CAST_B = 71260\n\n--Rune Color Types\n-- 1 Orange 102787\n-- 2 Green 102788\n-- 3 Yellow 102789\n-- 4 Purple 102790\n-- 5 Blue 102791\n-- 6 Red 102792\n\nDEATH_ANIM_KIT = 0\nFALL_ANIM_KIT = 9091\nMOVE_TIME = 0.3\nFALL_TIME = 0.2\nDEATH_TIME = 2.0\nDISPLAY = {102787, 102788, 102789, 102790, 102791, 102792}\nDROPS = {0, 0, 0, 0, 0, 0}\nSCORE_MATCH = 1000\nSCORE_ADDITIONAL = 750\n\nBACKGROUND_CREATURE = 184575\nSCALE_BACKGROUND = 2.2\nBACKGROUND_FRONT = 2.2\nBACKGROUND_HEIGHT = 2.2\nbackgroundOffset = Vector:New(BACKGROUND_FRONT, 0, BACKGROUND_HEIGHT)\n\nselected = nil\ngems = {}\nsceneFacing = 180\nswitching = false\n\nsceneOffset = Vector:New(GAME_FRONT, -(ROWS-1)*GEM_SPACING/2 -0.5, GAME_HEIGHT)\n\nfallVector = Vector:New(-.01, 0, -1*GEM_SPACING)\ndeathVector = Vector:New(5, 0, -5)\n\n\ngemCreateData = ActorCreateData:Default()\ngemCreateData.groundSnap = false\ngemCreateData.interactible = true\ngemCreateData.selectable = false\ngemCreateData.floatingTooltip = true\ngemCreateData.scale = SCALE_GEM\n\nlastSwitchedA = nil\nlastSwitchedB = nil\n\n\nscore = 0\nUNLOCK_SCORE_THRESHOLD = 30000\nachievementUnlocked = false\n--ACHIEVEMENT_SCORE_THRESHOLD = 250000', 42423),
(34260, '9.2 ZM - Puzzle - Match 3 Game - Functions C', 'function CreateBackground()\n\t\n\tbackgroundCreateData = ActorCreateData:Default()\n\tbackgroundCreateData.groundSnap = false\n\tbackgroundCreateData.interactible = false\n\tbackgroundCreateData.selectable = false\n\tbackgroundCreateData.floatingTooltip = false\n\tbackgroundCreateData.scale = SCALE_BACKGROUND\n\tbackgroundCreateData.creatureID = BACKGROUND_CREATURE\n\tbackgroundCreateData.disableUpdates = false\n\n\tbackgroundCreateData.transform = Transform:New(sceneOffset, 0, 90, 0)\n\n\tlocal background = scene:SpawnActor(backgroundCreateData)\n\t--background.selected = false\n\t--background.offset = nodeOffset\n\t--background.myVisual = nil\n\tbackground.isBackground = true\n\n--\tbackground:MoveToAbs(playerDisplay:GetPosition()+sceneOffset, 0)\n\tbackground:MoveToAbs(backgroundOffset, 0)\n\treturn background\n\nend', 42423),
(34259, '9.2 ZM - Puzzle - Match 3 Game - Functions C', 'function CreateBackground()\n\t\n\tbackgroundCreateData = ActorCreateData:Default()\n\tbackgroundCreateData.groundSnap = false\n\tbackgroundCreateData.interactible = false\n\tbackgroundCreateData.selectable = false\n\tbackgroundCreateData.floatingTooltip = false\n\tbackgroundCreateData.scale = SCALE_BACKGROUND\n\tbackgroundCreateData.creatureID = BACKGROUND_CREATURE\n\tbackgroundCreateData.disableUpdates = false\n\n\tbackgroundCreateData.transform = Transform:New(sceneOffset, 0, 90, 0)\n\n\tlocal background = scene:SpawnActor(backgroundCreateData)\n\t--background.selected = false\n\t--background.offset = nodeOffset\n\t--background.myVisual = nil\n\tbackground.isBackground = true\n\n--\tbackground:MoveToAbs(playerDisplay:GetPosition()+sceneOffset, 0)\n\tbackground:MoveToAbs(backgroundOffset, 0)\n\treturn background\n\nend', 42423),
(33500, '9.2 ZM - Puzzle - Match 3 Game - Action', 'PATH_ID_CAMERA_START = 30984\nPATH_ID_CAMERA_END = 30986\n\nscene:SetFadeRegion(50000, true)\n\nlocal gemCam = 804\nSetCameraFollowPath( gemCam, 1, PATH_ID_CAMERA_START, PATH_ID_CAMERA_END, 100000)\nlocal background = CreateBackground()\n--Broadcast(\"BACKGROUND\")\n--Broadcast(background)\n--Broadcast(\"BACKGROUND\")\n--Broadcast(background.isBackground)\n\n--INIT GEMS------------------------------------------------------------\nfor i=1, COLUMNS do\n\tgems[i] = {}\n\tfor j=1, ROWS do\n\t\tCreateGem(i, j, 0)\n\tend\nend\n\n--CHECK ONCE------------------------------------------------------------\nCheckForMatches()\n\n\nwhile (true) do\n\tWait(300)\nend', 42423),
(33499, '9.2 ZM - Puzzle - Match 3 Game - Functions B', 'function GemDelete(gem)\n\t--Grant deletion credit\n\t--[[local gemcolor = scene:GetWorldState(17663)\n\tif gem.type == gemcolor then\n\t\tscene:TriggerServerEvent(\"win_toast\")\n\t\tscene:TriggerServerEvent(\"win\")\n\tend]]--\n\n\tlocal row = gem.row\n\tlocal col = gem.col\n\tif gem.deleted==false then\n\t\tgem.deleted=true\n\t\tfor j=1,row-1 do\n\t\t\tif gems[col][j]~= nil then\n\t\t\t\t--Broadcast(\"Incrementing rows to fall\")\n\t\t\t\tgems[col][j].rowsToFall = gems[col][j].rowsToFall + 1\n\t\t\tend\n\t\tend\n\tend\nend \n\nfunction CreateGem(column, row, height)\n\t--Broadcast(\"Creating gem at col \"..column..\", row \"..row..\", height \"..height)\n\n\tlocal type = math.random(#DISPLAY)\n\tgemCreateData.creatureDisplayID = DISPLAY[type]\n\n\tflyerDrop = DROPS[type]\n\n\tlocal gemOffset = Vector:New(0, column*GEM_SPACING, (height-row)*GEM_SPACING - flyerDrop)\n\tgemCreateData.transform = Transform:New(sceneOffset+gemOffset, playerDisplay:GetTransform().yaw+180, 0, 0)\n\n\tgems[column][row] = scene:SpawnActor(gemCreateData)\n\tgems[column][row]:SetInteractCursor(\"interact\", CursorRange.RangeFromPlayer, 20, nil)\n\tgems[column][row].col = column\n\tgems[column][row].row = row\n\tgems[column][row].selected = false\n\tgems[column][row].myVisual = nil\n\tgems[column][row].type = type\n\tgems[column][row].deleted = false\n\tgems[column][row].rowsToFall = 0\n\tgems[column][row].height = height\n\tgems[column][row].dying = false\n\t--gems[column][row]:SetFacingToTarget(playerDisplay, Vector:New())\n\n\t--RideVehicleActor(gems[column][row], playerDisplay, 0, AttachmentPoint.Base, sceneOffset+gemOffset, Vector:New(playerDisplay:GetTransform().yaw+180, 0, 0))\n\tgems[column][row]:MoveToAbs(playerDisplay:GetPosition()+sceneOffset+gemOffset, 0)\n\tAddGemCoroutine(gems[column][row])\n\treturn gems[column][row]\n\nend\n\nfunction FaceForward()\n\tfor i=1, COLUMNS do\n\t\tfor j=1, ROWS do\n\t\t\tif gems[i][j]~= nil then\n\t\t\t\t--gems[i][j]:SetFacingToTarget(playerDisplay, Vector:New())\n\t\t\t\tgems[i][j]:StopAnimKit(FALL_ANIM_KIT)\n\t\t\t\tgems[i][j].isSelected = false\n\t\t\tend\n\t\tend\n\tend\nend\n\nlocal DeathCoroutine\nfunction AddDeathCoroutine(...)\n\tscene:AddCoroutineWithParams(DeathCoroutine, ...)\nend\nDeathCoroutine = function(actor)\n\tactor.dying = true\n\tactor.row = 1000000\n\tactor.col = 1000000\n\t--actor:SetFacingToTarget(playerDisplay, Vector:New())\n\t--actor:PlayLoopingAnimKit(4170)\n\tactor:PlaySpellCastVisual(EXPLOSION_CAST)\n\tlocal newPos = actor:GetPosition() + deathVector\n\tactor:MoveToAbs(newPos, DEATH_TIME)\n\tFadeOut(actor, DEATH_TIME)\n\tWait(DEATH_TIME)\n\tactor:Despawn()\nend  \n\n\nfunction PrettyNumberString( number )\n\tlocal string = tostring(number)\n\tlocal millions = string.sub(string, 1, string.len(string)-6)\n\tlocal thousands = string.sub(string, -6, -4)\n\tlocal singles = string.sub(string, -3)\n\tif number<1000 then\n\t\tstring = singles\n\telseif number<1000000 then\n\t\tstring = thousands..\",\"..singles\n\telse\n\t\tstring = millions..\",\"..thousands..\",\"..singles\n\tend\n\treturn string\nend\n\n\nfunction ShowScore(actor, amount)\n\tscore = score + amount\n\tlocal type = WorldText.Critical\n\t--actor:AddCustomWorldText( type, true, Color:New(250,100,250), \"?\" ) \n\n\t--Win check\n\tif score >= UNLOCK_SCORE_THRESHOLD then\n\t\tscene:TriggerServerEvent(\"win_toast\")\n\t\tscene:TriggerServerEvent(\"win\")\n\tend\nend', 42423),
(33498, '[1] 9.2 ZM - Puzzle - Match 3 Game - Functions A', 'matchCount=0\n\t\t\t\tend\n\t\t\t\tif matchCount==2 then\n\t\t\t\t\t--Broadcast(\"adding to delete table\")\n\t\t\t\t\tGemDelete(gems[i][j-2])\n\t\t\t\t\tGemDelete(gems[i][j-1])\n\t\t\t\t\tGemDelete(gems[i][j])\n\t\t\t\t\tShowScore(gems[i][j-1], SCORE_MATCH)\n\t\t\t\t\tmatchFound = true\n\t\t\t\telseif matchCount>2 then\n\t\t\t\t\tGemDelete(gems[i][j])\n\t\t\t\t\tShowScore(gems[i][j], SCORE_ADDITIONAL)\n\t\t\t\t\tmatchFound = true\n\t\t\t\tend\n--\t\t\t\tif matchCount >= 2 then\n--\t\t\t\t\tif thisType == gemcolor then\n--\t\t\t\t\t\tscene:TriggerServerEvent(\"win\")\n--\t\t\t\t\tend\n--\t\t\t\tend\n\t\t\tend\n\t\tend\n\t\tcurrentType = 0\n\t\tmatchCount = 0\n\tend\n\tcurrentType = 0\n\tmatchCount = 0\n\n\t--print(\"easy\")\n\n\t--Check horizontal matches\n\tfor j=1, ROWS do\n\t\tfor i=1, COLUMNS do\n\t\t\tif gems[i][j]~= nil then\n\t\t\t\tlocal thisType = gems[i][j].type\n\t\t\t\tif thisType==currentType then\n\t\t\t\t\tmatchCount = matchCount+1\n\t\t\t\telse\n\t\t\t\t\tcurrentType=thisType\n\t\t\t\t\tmatchCount=0\n\t\t\t\tend\n\t\t\t\tif matchCount==2 then\n\t\t\t\t\tGemDelete(gems[i-2][j])\n\t\t\t\t\tGemDelete(gems[i-1][j])\n\t\t\t\t\tGemDelete(gems[i][j])\n\t\t\t\t\tShowScore(gems[i-1][j], SCORE_MATCH)\n\t\t\t\t\tmatchFound = true\t\n\t\t\t\telseif matchCount>2 then\n\t\t\t\t\tGemDelete(gems[i][j])\n\t\t\t\t\tShowScore(gems[i][j], SCORE_ADDITIONAL)\n\t\t\t\t\tmatchFound = true\n\t\t\t\tend\n--\t\t\t\tif matchCount >= 2 then\n--\t\t\t\t\tif thisType == gemcolor then\n--\t\t\t\t\t\tscene:TriggerServerEvent(\"win\")\n--\t\t\t\t\tend\n--\t\t\t\tend\n\t\t\tend\n\t\tend\n\t\tcurrentType = 0\n\t\tmatchCount = 0\n\tend\n\n\t\n\t--Delete matched actors\n\tfor i=1, COLUMNS do\n\t\tfor j=1, ROWS do\n\t\t\tif gems[i][j]~= nil then\n\t\t\t\tif gems[i][j].deleted==true then\n\t\t\t\t\tgaps[i] = gaps[i]+1\n\t\t\t\t\tAddDeathCoroutine(gems[i][j])\n\t\t\t\t\t--Broadcast(gems[i][j])\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\n\t--Set new row values\n\tfor i=1, COLUMNS do\n\t\tfor j=ROWS, 1, -1 do\n\t\t\tif gems[i][j]~= nil then\n\t\t\t\tlocal rowsToFall = gems[i][j].rowsToFall\n\t\t\t\tif (rowsToFall>0) then\n\t\t\t\t\tgems[i][j].row = gems[i][j].row+rowsToFall\n\t\t\t\t\tgems[i][j+rowsToFall] = gems[i][j]\n\t\t\t\t\tgems[i][j] = nil\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\n\n\t--Add replacements\n\tfor i=1, COLUMNS do\n\t\tfor j=1, gaps[i] do\n\t\t\tlocal type = math.random(#DISPLAY)\n\t\t\tlocal newGem = CreateGem(i,j,gaps[i])\n\t\tend\n\tend\n\n\t--Make them fall\n\tlocal maxFalls = 0\n\tfor i=1, COLUMNS do\n\t\tfor j=ROWS, 1, -1 do\n\t\t\tif gems[i][j]~= nil then\n\t\t\t\tlocal rowsToFall = gems[i][j].rowsToFall\n\t\t\t\tlocal height = gems[i][j].height\n\t\t\t\tif (rowsToFall+height) > 0 then\n\t\t\t\t\t--Broadcast(\"Falling \"..rowsToFall..\"+\"..height..\" rows\")\n\t\t\t\t\tif (rowsToFall+height) > maxFalls then\n\t\t\t\t\t\tmaxFalls = rowsToFall+height\n\t\t\t\t\tend\n\t\t\t\t\tlocal myFallVector = (rowsToFall+height) * fallVector\n\t\t\t\t\tlocal newPos = gems[i][j]:GetPosition() + myFallVector\n\t\t\t\t\t--gems[i][j]:MoveToAbs(newPos, FALL_TIME * (rowsToFall+height))\n\t\t\t\t\tlocal type = gems[i][j].type\n\t\t\t\t\tflyerDrop = DROPS[type]\n\n\t\t\t\t\tlocal gemOffset = Vector:New(0, i*GEM_SPACING, (-j)*GEM_SPACING - flyerDrop)\n\t\t\t\t\t--RideVehicleActor(gems[i][j], playerDisplay, FALL_TIME * (rowsToFall+height), AttachmentPoint.Base, sceneOffset+gemOffset, Vector:New(scene:GetTransform().yaw+180, 0, 0))\n\t\t\t\t\tgems[i][j]:MoveToAbs(playerDisplay:GetPosition() + sceneOffset+gemOffset, FALL_TIME * (rowsToFall+height))\n\t\t\t\t\tgems[i][j].rowsToFall = 0\n\t\t\t\t\tgems[i][j].height = 0\n\t\t\t\t\tgems[i][j]:PlayLoopingAnimKit(9091)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\n\tWait(FALL_TIME*maxFalls)\n\tgaps = {}\n\tFaceForward()\n\t\n\tif matchFound==true then\n\t\tCheckForMatches(false)\n\telse\n\t\tif firstMove==true then\n\t\t\tSwitch(lastSwitchedA, lastSwitchedB, true)\n\t\tend\n\t\tfalling = false\n\tend\n\t\nend\n\n', 42423),
(33496, '9.2 ZM - Puzzle - Match 3 Game - Medium - Globals', 'scene:SetRelativeCoords(true)\nplayerDisplay = scene:GetActivePlayerDisplay()\n\nGAME_TIME = 300\nGAME_DISTANCE = 25\nSCALE_GEM = .1\nGEM_SPACING = 0.2\nFLYER_HEIGHT = 0.08\nROWS = 7\nCOLUMNS = 9\nGAME_HEIGHT = 2.85\nGAME_FRONT = 1.0\nSELECTED_STATE = 110872\nEXPLOSION_CAST = 110873\nCLICK_CAST_A = 71257\nCLICK_CAST_B = 71258\nSLIDE_CAST_A = 71259\nSLIDE_CAST_B = 71260\n\n--Rune Color Types\n-- 1 Orange 102787\n-- 2 Green 102788\n-- 3 Yellow 102789\n-- 4 Purple 102790\n-- 5 Blue 102791\n-- 6 Red 102792\n\nDEATH_ANIM_KIT = 0\nFALL_ANIM_KIT = 9091\nMOVE_TIME = 0.3\nFALL_TIME = 0.2\nDEATH_TIME = 2.0\nDISPLAY = {102788, 102791, 102789, 102792, 102787}\nDROPS = {0, 0, 0, 0, 0, 0}\nSCORE_MATCH = 1000\nSCORE_ADDITIONAL = 750\n\nBACKGROUND_CREATURE = 184575\nSCALE_BACKGROUND = 2.2\nBACKGROUND_FRONT = 2\nBACKGROUND_HEIGHT = 2.2\nbackgroundOffset = Vector:New(BACKGROUND_FRONT, 0, BACKGROUND_HEIGHT)\n\nselected = nil\ngems = {}\nsceneFacing = 180\nswitching = false\n\nsceneOffset = Vector:New(GAME_FRONT, -(ROWS-1)*GEM_SPACING/2 -0.5, GAME_HEIGHT)\n\nfallVector = Vector:New(-.01, 0, -1*GEM_SPACING)\ndeathVector = Vector:New(5, 0, -5)\n\n\ngemCreateData = ActorCreateData:Default()\ngemCreateData.groundSnap = false\ngemCreateData.interactible = true\ngemCreateData.selectable = false\ngemCreateData.floatingTooltip = true\ngemCreateData.scale = SCALE_GEM\n\nlastSwitchedA = nil\nlastSwitchedB = nil\n\n\nscore = 0\nUNLOCK_SCORE_THRESHOLD = 30000\nachievementUnlocked = false\n--ACHIEVEMENT_SCORE_THRESHOLD = 250000', 42423),
(33495, '9.2 ZM - Puzzle - Match 3 Game - Action', 'PATH_ID_CAMERA_START = 30984\nPATH_ID_CAMERA_END = 30986\n\nscene:SetFadeRegion(50000, true)\n\nlocal gemCam = 804\nSetCameraFollowPath( gemCam, 1, PATH_ID_CAMERA_START, PATH_ID_CAMERA_END, 100000)\nlocal background = CreateBackground()\n--Broadcast(\"BACKGROUND\")\n--Broadcast(background)\n--Broadcast(\"BACKGROUND\")\n--Broadcast(background.isBackground)\n\n--INIT GEMS------------------------------------------------------------\nfor i=1, COLUMNS do\n\tgems[i] = {}\n\tfor j=1, ROWS do\n\t\tCreateGem(i, j, 0)\n\tend\nend\n\n--CHECK ONCE------------------------------------------------------------\nCheckForMatches()\n\n\nwhile (true) do\n\tWait(300)\nend', 42423),
