nd\n\n\t--Set new row values\n\tfor i=1, COLUMNS do\n\t\tfor j=ROWS, 1, -1 do\n\t\t\tif gems[i][j]~= nil then\n\t\t\t\tlocal rowsToFall = gems[i][j].rowsToFall\n\t\t\t\tif (rowsToFall>0) then\n\t\t\t\t\tgems[i][j].row = gems[i][j].row+rowsToFall\n\t\t\t\t\tgems[i][j+rowsToFall] = gems[i][j]\n\t\t\t\t\tgems[i][j] = nil\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\n\n\t--Add replacements\n\tfor i=1, COLUMNS do\n\t\tfor j=1, gaps[i] do\n\t\t\tlocal type = math.random(#DISPLAY)\n\t\t\tlocal newGem = CreateGem(i,j,gaps[i])\n\t\tend\n\tend\n\n\t--Make them fall\n\tlocal maxFalls = 0\n\tfor i=1, COLUMNS do\n\t\tfor j=ROWS, 1, -1 do\n\t\t\tif gems[i][j]~= nil then\n\t\t\t\tlocal rowsToFall = gems[i][j].rowsToFall\n\t\t\t\tlocal height = gems[i][j].height\n\t\t\t\tif (rowsToFall+height) > 0 then\n\t\t\t\t\t--Broadcast(\"Falling \"..rowsToFall..\"+\"..height..\" rows\")\n\t\t\t\t\tif (rowsToFall+height) > maxFalls then\n\t\t\t\t\t\tmaxFalls = rowsToFall+height\n\t\t\t\t\tend\n\t\t\t\t\tlocal myFallVector = (rowsToFall+height) * fallVector\n\t\t\t\t\tlocal newPos = gems[i][j]:GetPosition() + myFallVector\n\t\t\t\t\t--gems[i][j]:MoveToAbs(newPos, FALL_TIME * (rowsToFall+height))\n\t\t\t\t\tlocal type = gems[i][j].type\n\t\t\t\t\tflyerDrop = DROPS[type]\n\n\t\t\t\t\tlocal gemOffset = Vector:New(0, i*GEM_SPACING, (-j)*GEM_SPACING - flyerDrop)\n\t\t\t\t\t--RideVehicleActor(gems[i][j], playerDisplay, FALL_TIME * (rowsToFall+height), AttachmentPoint.Base, sceneOffset+gemOffset, Vector:New(scene:GetTransform().yaw+180, 0, 0))\n\t\t\t\t\tgems[i][j]:MoveToAbs(playerDisplay:GetPosition() + sceneOffset+gemOffset, FALL_TIME * (rowsToFall+height))\n\t\t\t\t\tgems[i][j].rowsToFall = 0\n\t\t\t\t\tgems[i][j].height = 0\n\t\t\t\t\tgems[i][j]:PlayLoopingAnimKit(9091)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\n\tWait(FALL_TIME*maxFalls)\n\tgaps = {}\n\tFaceForward()\n\t\n\tif matchFound==true then\n\t\tCheckForMatches(false)\n\telse\n\t\tif firstMove==true then\n\t\t\tSwitch(lastSwitchedA, lastSwitchedB, true)\n\t\tend\n\t\tfalling = false\n\tend\n\t\nend\n\n', 42423),
(35040, '[1] 9.1 World Quest - Light\'s Out - Functions (Tutorial)', 'scene:AddCoroutineWithParams(NodeCoroutine, ...)\nend\nNodeCoroutine = function(actor)\n\twhile (true) do\n\t\tactor:WaitRightClick()\n\t--\tBroadcast(\"Clicked\")\n\t\tif InteractionAllowed() then\n\t\t\tscene:PlaySoundKit(193443,true,scene:GetPosition())\n\t\t\tDisableInteraction()\n\t\t\tFlipLights(actor.Row,actor.Col)\n\t\t\tDisplayBoard()\n\t\t\tEnableInteraction()\n\t\telse\n\t\tend\n\tend\nend\n\nfunction CreateNode(Row,Column,PassedValue)\n\n\tNodeCreateData.creatureDisplayID = NODE_CDI\n\tlocal nodeOffset = Vector:New(0,Column*COLUMN_WIDTH,Row*ROW_HEIGHTH)\n\tNodeCreateData.transform = Transform:New(BOARD_OFFSET+nodeOffset, scene:GetTransform().yaw, 0, 0)\n\tNodeCreateData.scale=NODE_SCALE\n\tNodeCreateData.interactible=true\n\t\n\tlocal thisNode = scene:SpawnActor(NodeCreateData)\n\tthisNode:SetInteractCursor(\"interact\", CursorRange.RangeFromPlayer, 20, nil)\n\tthisNode.selected = false\n\tthisNode.offset = nodeOffset\n\tthisNode.LitUp = false\n\t--thisNode.SpellVisual = NODE_STATE_VISUAL_DARK\n\tthisNode.Row=Row\n\tthisNode.Col=Column\n\t\n\tRideVehicleActor(thisNode, Player, 0, AttachmentPoint.Base,BOARD_OFFSET+nodeOffset+VEHICLE_OFFSET_Z,Vector:New(0,0,0))--scene:GetTransform().yaw\n\tAddInteractCoroutine(thisNode)\n\treturn thisNode\n\nend\n\nfunction DisplayOpening()\n\tif not GameBoard.AlreadyPlayedIntroLine1 then\n\t\tGameBoard.AlreadyPlayedIntroLine1=true\n\t\tscene:TriggerServerEvent(\"IntroA\")\n\t\tWait(4)\n\tend\n\tscene:TriggerServerEvent(\"IntroB\")\n\tWait(10)\nend\n\nfunction CreateGameBoard(PassedLocation)\n\tDisableInteraction()\n\tlocal BoardCreateData = ActorCreateData:Default()\n\tBoardCreateData.groundSnap = true\n\tBoardCreateData.interactible = false\n\tBoardCreateData.selectable = false\n\tBoardCreateData.floatingTooltip = false\n\tBoardCreateData.scale = BOARD_SCALE\n\tBoardCreateData.creatureDisplayID = BOARD_CDI\n\tBoardCreateData.offset=Vector:New(0,0,0)\n\t\n\tlocal MyBoard = scene:SpawnActor(BoardCreateData)\n\tMyBoard.selected = false\n\ttable.insert(SpellVisualsToClear,{MyBoard,MyBoard:PlaySpellStateVisual(BOARD_STATE_VISUAL)})\n\t\n\tRideVehicleActor(MyBoard, Player, 0, AttachmentPoint.Base,Vector:New(.15,-0.15,.22)+BOARD_OFFSET+VEHICLE_OFFSET_Z,Vector:New(0,0,0))--Vector:New(0,0,0),Vector:New(scene:GetTransform().yaw,0,0))\n\tfor i=1,MaxDimensions[\"MaxRows\"] do\t\t\t\n\t\tGameBoard[i]={}\n\t\tfor j=1,MaxDimensions[\"MaxCols\"] do\n\t\t\tGameBoard[i][j]=CreateNode(i,j,1)\n\t\tend\n\tend\n\tWait(1)\n\tGameParameters[\"movesremaining\"]=GameParameters[\"maxmoves\"]\n\t\n\tScrambleBoard()\n\t\n\tDisplayBoard(true)\n\t\n\tEnableInteraction()\n\t\n\tDisplayOpening()\t\t\nend\n\nfunction DisplayBoard(Initial)\n\tif not GameBoard then\n\t\tBroadcast(\"[CS30435] No GameBoard to display!\")\n\t\treturn\n\tend\n\tscene:PlaySoundKit(193446,true,scene:GetPosition())\n\tlocal DisplayRow\n\tfor i=1,MaxDimensions[\"MaxRows\"] do\n\t\tDisplayRow=\"Row[\"..i..\"]\"\n\t\tfor j=1,MaxDimensions[\"MaxCols\"] do\n\t\t\tif GameBoard and GameBoard[i] and GameBoard[i][j] then\n\t\t\t\tif GameBoard[i][j].LitUp and Initial then\n\t\t\t\t\t--Show Lit up Visual\n\t\t\t\t\tManageNodeVisual(GameBoard[i][j],NODE_STATE_VISUAL_LITUP)\n\t\t\t\t\t--GameBoard[i][j].SpellVisual=GameBoard[i][j]:PlaySpellStateVisual(NODE_STATE_VISUAL_LITUP)\n\t\t\t\t\ttable.insert(SpellVisualsToClear,{GameBoard[i][j],GameBoard[i][j].SpellVisual})\n\t\t\t\telseif not GameBoard[i][j].LitUp and Initial then\n\t\t\t\t\t--Show Not Lit Up\n\t\t\t\t\tManageNodeVisual(GameBoard[i][j],NODE_STATE_VISUAL_DARK)--NODE_STATE_VISUAL_DARK\n\t\t\t\t\t--GameBoard[i][j].SpellVisual=GameBoard[i][j]:PlaySpellStateVisual(NODE_STATE_VISUAL_DARK)\n\t\t\t\t\ttable.insert(SpellVisualsToClear,{GameBoard[i][j],GameBoard[i][j].SpellVisual})\n\t\t\t\tend\n\t\t\t\tDisplayRow=DisplayRow..tostring(GameBoard[i][j].LitUp)..\" \"\t\t\n\t\t\telse\n\t\t\tend\n\t\tend\n\t\tif PassedParameters and PassedParameters[\"debug\"]==true then\n\t\t\tBroadcast(DisplayRow)\n\t\tend\n\tend\n\t\nend\n\nfunction ScrambleBoard()\n\tif not GameParameters then \n\t\t', 42423),
(35039, '9.1 World Quest - Light\'s Out - Functions (Tutorial)', 'function ManageNodeVisual(PassedNode,PassedVisual)\n\tif PassedNode.SpellVisual then\n\t--Broadcast(\"Clearing SpellVisual: \"..PassedNode.SpellVisual)\n\t\tPassedNode:ClearSpellVisual(PassedNode.SpellVisual)\n\tend\n\tif PassedVisual then\n\t--Broadcast(\"Starting State Visual: \"..PassedVisual)\n\t--Broadcast(\"Starting State Visual: \"..NODE_STATE_VISUAL_LITUP)\n\t\tPassedNode.SpellVisual=PassedNode:PlaySpellStateVisual(PassedVisual)\n\t\ttable.insert(SpellVisualsToClear,{PassedNode,PassedNode.SpellVisual})\n\telse\n\t\tPassedNode.SpellVisual=nil\n\tend\nend\n\nfunction CleanUpGame()\n\tlocal LoopUnit\n\tlocal LoopSpellVisual\n\tfor i=1,#SpellVisualsToClear do\n\t\tLoopUnit=SpellVisualsToClear[i][1]\n\t\tLoopSpellVisual=SpellVisualsToClear[i][2]\n\t\tif LoopUnit then\n\t\t\tif LoopUnit.ClearSpellVisual then\n\t\t\t\tif LoopSpellVisual then\n\t\t\t\t\tLoopUnit:ClearSpellVisual(LoopSpellVisual)\n\t\t\t\tend\n\t\t\telse\n\t\t\t\tBroadcast(\"LoopUnit doesn\'t have ClearSpellVisual?\")\n\t\t\tend\n\t\telse\n\t\t\tif LoopSpellVisual then\n\t\t\t\tBroadcast(\"Failed to Clear Spell Visual due to bad unit:\"..LoopSpellVisual)\n\t\t\telse\n\t\t\t\tBroadcast(\"Found an invalid unit and spellvisual entry.\")\n\t\t\tend\n\t\tend\n\t\tLoopUnit,LoopSpellVisual=nil,nil\n\tend\nend\n\nfunction ClearBoard()\n\tif not GameBoard then return end\n\tfor i=1,MaxDimensions[\"MaxRows\"] do\n\t\tfor j=1,MaxDimensions[\"MaxCols\"] do\n\t\t\tif GameBoard and GameBoard[i] and GameBoard[i][j] then\n\t\t\t\tif GameBoard[i][j].SpellVisual then\n\t\t\t\t\tGameBoard[i][j]:ClearSpellVisual(GameBoard[i][j].SpellVisual)\n\t\t\t\tend\n\t\t\t\tGameBoard[i][j]:Despawn()\n\t\t\t\tGameBoard[i][j]=nil\t\t\t\n\t\t\tend\n\t\tend\n\t\tGameBoard[i]=nil\n\tend\nend\n\nfunction DisableInteraction()\n\tGameBoard.InteractionDisabled=true\nend\n\nfunction EnableInteraction()\n\tGameBoard.InteractionDisabled=nil\nend\n\nfunction InteractionAllowed()\n\tif not GameBoard then return false end\n\treturn not GameBoard.InteractionDisabled\nend\n\nfunction FailGame()\n\tscene:TriggerServerEvent(\"Failure\")\n\tDisableInteraction()\n\tClearBoard()\n\tWait(3)\n\tRestartGame()\nend\n\nfunction MakeGameNodes()\n\tfor i=1,MaxDimensions[\"MaxRows\"] do\t\t\t\n\t\tGameBoard[i]={}\n\t\tfor j=1,MaxDimensions[\"MaxCols\"] do\n\t\t\tGameBoard[i][j]=CreateNode(i,j,1);\n\t\tend\n\tend\nend\n\nfunction RestartGame()\n\tDisableInteraction()\n\tClearBoard()\n\tMakeGameNodes()\n\t--GameParameters[\"movesremaining\"]=GameParameters[\"maxmoves\"]\n\tScrambleBoard()\n\tDisplayBoard(GameParameters)\n\tEnableInteraction()\n\tDisplayOpening()\nend\n\t\nfunction FlipLights(PassedRow,PassedCol)\n\tlocal Offsets={ {0,1},{0,0},{0,-1},{-1,0},{1,0} }\n\tfor _,LoopOffset in pairs(Offsets) do\n\t\tif GameBoard[PassedRow+LoopOffset[1]] then\n\t\t\tif GameBoard[PassedRow+LoopOffset[1]][PassedCol+LoopOffset[2]] then\n\t\t\t\t--Broadcast(\"Node[\"..PassedRow+LoopOffset[1]..\"][\"..PassedCol+LoopOffset[2]..\"]: \"..tostring(GameBoard[PassedRow+LoopOffset[1]][PassedCol+LoopOffset[2]].LitUp))\n\t\t\t\tif GameBoard[PassedRow+LoopOffset[1]][PassedCol+LoopOffset[2]].LitUp==true then\n\t\t\t\t\t--Broadcast(\"Turning off Node[\"..PassedRow+LoopOffset[1]..\"][\"..PassedCol+LoopOffset[2]..\"]\")\n\t\t\t\t\tGameBoard[PassedRow+LoopOffset[1]][PassedCol+LoopOffset[2]].LitUp=false\n\t\t\t\t\tManageNodeVisual(GameBoard[PassedRow+LoopOffset[1]][PassedCol+LoopOffset[2]],NODE_STATE_VISUAL_DARK)\n\t\t\t\telse\n\t\t\t\t\t--Broadcast(\"Turning on Node[\"..PassedRow+LoopOffset[1]..\"][\"..PassedCol+LoopOffset[2]..\"]\")\n\t\t\t\t\tGameBoard[PassedRow+LoopOffset[1]][PassedCol+LoopOffset[2]].LitUp=true\n\t\t\t\t\tManageNodeVisual(GameBoard[PassedRow+LoopOffset[1]][PassedCol+LoopOffset[2]],NODE_STATE_VISUAL_LITUP)\n\t\t\t\tend\n\t\t\telse\n\t\t\t\t--Broadcast(\"Couldn\'t find column entry for Node[\"..PassedRow+LoopOffset[1]..\"][\"..PassedCol+LoopOffset[2]..\"]\")\n\t\t\tend\n\t\telse\n\t\t\t--Broadcast(\"Couldn\'t find row entry for Node[\"..PassedRow+LoopOffset[1]..\"][\"..PassedCol+LoopOffset[2]..\"]\")\n\t\tend\n\tend\nend\n\n\nlocal NodeCoroutine\nfunction AddInteractCoroutine(...)\n\t', 42423),
(34983, '[2] 9.1 World Quest - Berlekamp (Tutorial) - Functions', 'AttachmentPoint.Base,BOARD_OFFSET+VEHICLE_OFFSET_Z,Vector:New(0,0,0))--Vector:New(0,0,0),Vector:New(scene:GetTransform().yaw,0,0))\n\t--Need to place interacts on the outside edges..\n\tfor i=1,MaxDimensions[\"MaxRows\"] do\n\t\tCreateInteract(i,-1)--yes, -1 looks weird.  It\'s ok.\n\tend\n\tfor i=1,MaxDimensions[\"MaxCols\"] do\n\t\tCreateInteract(-1,i)\n\tend\n\t\n\tfor i=1,MaxDimensions[\"MaxRows\"] do\t\t\t\n\t\tGameBoard[i]={}\n\t\tfor j=1,MaxDimensions[\"MaxCols\"] do\n\t\t\tGameBoard[i][j]=CreateNode(i,j,-1)\n\t\tend\n\tend\n\t\n\tGameParameters[\"movesremaining\"]=GameParameters[\"maxmoves\"]\n\t\n\tScrambleBoard(GameBoard,GameParameters)\n\t\n\tDisplayBoard(GameParameters)\n\t\n\tEnableInteraction()\n\t\n\tDisplayOpening()\nend\n\nfunction DisplayBoard(PassedParameters)\n\tif not GameBoard then\n\t\tBroadcast(\"[CS30435] No GameBoard to display!\")\n\t\treturn\n\tend\n\tlocal DisplayRow\n\tfor i=1,MaxDimensions[\"MaxRows\"] do\n\t\tDisplayRow=\"Row[\"..i..\"]\"\n\t\tfor j=1,MaxDimensions[\"MaxCols\"] do\n\t\t\tif GameBoard and GameBoard[i] and GameBoard[i][j] then\n\t\t\t\tif GameBoard[i][j].LitUp > 0 then\n\t\t\t\t\t--Show Lit up Visual\n\t\t\t\t\tManageNodeVisual(GameBoard[i][j],NODE_STATE_VISUAL_LITUP)\n\t\t\t\telseif GameBoard[i][j].LitUp < 0 then\n\t\t\t\t\t--Show Not Lit Up\n\t\t\t\t\tManageNodeVisual(GameBoard[i][j],NODE_STATE_VISUAL_DARK)\n\t\t\t\tend\n\t\t\t\tDisplayRow=DisplayRow..GameBoard[i][j].LitUp..\" \"\t\t\n\t\t\telse\n\t\t\tend\n\t\tend\n\t\tif PassedParameters and PassedParameters[\"debug\"]==true then\n\t\t\tBroadcast(DisplayRow)\n\t\tend\n\tend\n\t\nend\n\nfunction ScrambleBoard(PassedBoard,PassedParameters)\n\tif not PassedParameters then \n\t\tPassedParameters={[\"complexity\"]=0,[\"allowduplicates\"]=nil,[\"allowrepeats\"]=false}\n\tend\n\n\t--Build table of all scrambling moves\n\tlocal ScramblingMoves={}\n\tfor i=1,MaxDimensions[\"MaxRows\"] do\n\t\ttable.insert(ScramblingMoves,{[\"target\"]=\"column\",\t[\"value\"]=i})\n\tend\n\tfor i=1,MaxDimensions[\"MaxCols\"] do\n\t\ttable.insert(ScramblingMoves,{[\"target\"]=\"row\",\t[\"value\"]=i})\n\tend\n\t\n\t\n\tlocal LoopMove\n\tfor i=1,PassedParameters[\"complexity\"] do\n\t\tif i==1 or PassedParameters[\"allowrepeats\"] then\n\t\t\tLoopMove=table.remove(ScramblingMoves,math.random(1,#ScramblingMoves))\n\t\telse\n\t\t\tLoopMove=table.remove(ScramblingMoves,math.random(1,#ScramblingMoves-1))--Don\'t use the end of the list, that was the last move\n\t\tend\n\t\tif PassedParameters[\"debug\"] then\n\t\t\tBroadcast(\"Move[\"..i..\"]: \"..LoopMove[\"target\"]..\": \"..LoopMove[\"value\"])\n\t\tend\n\t\tif LoopMove[\"target\"]==\"row\" then\n\t\t\tfor column=1,MaxDimensions[\"MaxCols\"] do\n\t\t\t\tPassedBoard[LoopMove[\"value\"]][column].LitUp=-1*PassedBoard[LoopMove[\"value\"]][column].LitUp\n\t\t\tend\n\t\telseif LoopMove[\"target\"]==\"column\" then\n\t\t\tfor row=1,MaxDimensions[\"MaxRows\"] do\n\t\t\t\tPassedBoard[row][LoopMove[\"value\"]].LitUp=-1*PassedBoard[row][LoopMove[\"value\"]].LitUp\n\t\t\tend\n\t\tend\n\t\tif PassedParameters[\"allowduplicates\"] then\n\t\t\ttable.insert(ScramblingMoves,LoopMove)\n\t\tend\n\tend\nend\n\nfunction GameIsFinished()\n\tif not GameBoard then return false end\n\tfor i=1,MaxDimensions[\"MaxRows\"] do\n\t\tfor j=1,MaxDimensions[\"MaxCols\"] do\n\t\t\tif GameBoard then\n\t\t\t\tif GameBoard[i] then\n\t\t\t\t\tif GameBoard[i][j] then \n\t\t\t\t\t\tif GameBoard[i][j].LitUp==1 then return false end\n\t\t\t\t\telse\n\t\t\t\t\t\t--Broadcast(\"No entry for Node[\"..i..\"][\"..j..\"]\")\n\t\t\t\t\t\treturn false\n\t\t\t\t\tend\n\t\t\t\telse\n\t\t\t\t\t--Broadcast(\"No entry for Row[\"..i..\"]\")\n\t\t\t\t\treturn false\n\t\t\t\tend\n\t\t\telse\n\t\t\t\t--Broadcast(\"No GameBoard found?\")\n\t\t\t\treturn false\n\t\t\tend\n\t\tend\n\tend\n\treturn true\t\t\t\nend', 42423),
