nteractionAllowed()\n\tif not GameBoard then return false end\n\treturn not GameBoard.InteractionDisabled\nend\n\nfunction FailGame()\n\tBroadcast(\"Game failed, clearing board\")\n\tDisableInteraction()\n\tClearBoard()\n\tBroadcast(\"Restarting in 3...\")\n\tWait(1)\n\tBroadcast(\"Restarting in 2..\")\n\tWait(1)\n\tBroadcast(\"Restarting in 1.\")\n\tWait(1)\n\tRestartGame()\nend\n\nfunction RestartGame()\n\tBroadcast(\"Restarting Game\")\n\tDisableInteraction()\n\tClearBoard()\n\tConstructDeck()\n\tMakeGameNodes()\n\t--GameParameters[\"movesremaining\"]=GameParameters[\"maxmoves\"]\n\tScrambleBoard()\n\tDisplayBoard(GameParameters)\n\tDisplayOpening()\n\tEnableInteraction()\nend\n\n\nfunction DisplayOpening()\n\tscene:PlaySoundKit(193446,true,scene:GetPosition())\t\n\tBroadcast(\"Make sets according to the following criteria:\")\n\tWait(1)\n\tBroadcast(\"Select three cards, such that they are either all alike or all different in each of the following categories:\")\n\tWait(1)\n\tBroadcast(\"Shape, Number of Shapes, Shape of Surrounding Element, Number of Surrounding Elements.\")\n\tWait(1)\n\tBroadcast(\"Good luck!\")\nend\n\n\nfunction MakeAllButListUninteractible(PassedList)\n\tif not GameBoard then\n\t\tBroadcast(\"[CS30435] No GameBoard to display!\")\n\t\treturn\n\tend\n\tfor i=1,MaxDimensions[\"MaxRows\"] do\n\t\tfor j=1,MaxDimensions[\"MaxCols\"] do\n\t\t\tif GameBoard and GameBoard[i] and GameBoard[i][j] then\n\t\t\t\tGameBoard[i][j]:SetInteractible(false)\n\t\t\t\tGameBoard[i][j].interactible=nil\n\t\t\tend\n\t\tend\n\tend\n\tfor _,LoopNode in pairs(PassedList) do\n\t\tif LoopNode then\n\t\t\tLoopNode:SetInteractible(true)\n\t\t\tLoopNode.interactible=true\n\t\tend\n\tend\nend\n\nfunction DisplayBoard()\n\tif not GameBoard then\n\t\tBroadcast(\"[CS30435] No GameBoard to display!\")\n\t\treturn\n\tend\n\tfor i=1,MaxDimensions[\"MaxRows\"] do\n\t\tfor j=1,MaxDimensions[\"MaxCols\"] do\n\t\t\tif GameBoard and GameBoard[i] and GameBoard[i][j] then\n\t\t\t\tif GameBoard[i][j].SpellVisuals and #GameBoard[i][j].SpellVisuals>0 then\n\t\t\t\t\tGameBoard[i][j]:SetInteractible(true)\n\t\t\t\t\tGameBoard[i][j].interactible=true\n\t\t\t\telse\n\t\t\t\t\t', 42423),
