INSERT INTO `mount_locale` (`ID`, `locale`, `Name_lang`, `SourceText_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(1552, 'deDE', 'Carzinisierter Zerethhirsch', '|cFFFFD200Quest:|r Leitmotive', 'Die wenigen, die von diesen mysteriösen Wesen noch verblieben sind, erscheinen unmöglich alt, fast schon zeitlos. Vielleicht wurden sie von den Ersten selbst erschaffen, da noch kein Bauplan gefunden wurde, um sie zu synthetisieren.', 42423),
(1572, 'deDE', 'Seelenfresser des kosmischen Gladiators', '|cFFFFD200Erfolg: |rGladiator: Saison 3 von Shadowlands|n|cFFFFD200Kategorie: |rSpieler gegen Spieler', 'Der Blick dieses Seelenfressers beunruhigt Euch. Ihr seht ihm besser nicht zu lang in die Augen.', 42423),
(1480, 'deDE', 'Seelenfresser des entfesselten Gladiators', '|cFFFFD200Erfolg: |rGladiator: Saison 2 von Shadowlands|n|cFFFFD200Kategorie: |rSpieler gegen Spieler', 'Der Blick dieses Seelenfressers beunruhigt Euch. Ihr seht ihm besser nicht zu lang in die Augen.', 42423),
(1549, 'deDE', 'Schimmernder Aurelid', '|cFFFFD200Erfolg: |rRuhm des Mausoleumsschlachtzüglers|n|cFFFFD200Kategorie: |rDungeons & Schlachtzüge', 'Obschon er einst geschaffen wurde, das Mausoleum der Ersten zu verteidigen, folgt er jetzt nach der Erfüllung seiner Primärfunktion gehorsam Euren Befehlen.', 42423);
