INSERT INTO `lfg_dungeons_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(2190, 'esES', 'La batalla de Ardenweald', '', 42423),
(2292, 'esES', 'Llanuras Efímeras', 'La esencia de la creación está siendo devorada. Si nadie hace nada, la realidad se desmoronará.', 42423),
(2291, 'esES', 'Piedra Angular de la Creación', 'Lihuvim libra una batalla perdida contra la dominación. A menos que alguien lo salve, el poder del guardián pasará a manos del Carcelero.', 42423);
