INSERT INTO `mount_locale` (`ID`, `locale`, `Name_lang`, `SourceText_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(1552, 'esES', 'Corcel de Zereth carcinizado', '|cFFFFD200Misión:|r Motivos rectores', 'Los pocos ejemplares que quedan de estas misteriosas criaturas parecen ser tremendamente viejos, casi intemporales. Puede que los creasen los Primeros, porque aún no se ha descubierto ningún esquema para sintetizarlos.', 42423),
(1572, 'esES', 'Comealmas de Gladiador Cósmico', '|cFFFFD200Logro: |rGladiador: Temporada 3 de Shadowlands|n|cFFFFD200Categoría: |rJugador contra jugador', 'La mirada del comealmas te perturba. Será mejor no mantener el contacto visual demasiado tiempo.', 42423),
(1480, 'esES', 'Comealmas de Gladiador desencadenado', '|cFFFFD200Logro: |rGladiador: Temporada 2 de Shadowlands|n|cFFFFD200Categoría: |rJugador contra jugador', 'La mirada del comealmas te perturba. Será mejor no mantener el contacto visual demasiado tiempo.', 42423),
(1549, 'esES', 'Aurélido fulgurante', '|cFFFFD200Logro: |rGloria del asaltante del Sepulcro|n|cFFFFD200Categoría: |rMazmorras y bandas', 'Aunque su finalidad original era defender el Sepulcro de los Primeros, ahora que ha completado su función principal, obedece tus órdenes.', 42423);
