INSERT INTO `mount_locale` (`ID`, `locale`, `Name_lang`, `SourceText_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(1552, 'esMX', 'Corcel de Zereth carcinado', '|cFFFFD200Misión:|r Música cautivante', 'Las pocas de estas misteriosas criaturas que quedan parecen ser increíblemente viejas, casi eternas. Tal vez fueron creadas por los Primeros, porque aún no se ha descubierto ningún esquema para sintetizarlas.', 42423),
(1572, 'esMX', 'Devorador de almas de Gladiador cósmico', '|cFFFFD200Logro: |rGladiador: Shadowlands, temporada 3|n|cFFFFD200Categoría: |rJugador contra jugador', 'La mirada de este devorador de almas es perturbadora. Será mejor que no lo mires de frente mucho tiempo.', 42423),
(1480, 'esMX', 'Devorador de almas de Gladiador desencadenado', '|cFFFFD200Logro: |rGladiador: Shadowlands, temporada 2|n|cFFFFD200Categoría: |rJugador contra jugador', 'La mirada de este devorador de almas es perturbadora. Será mejor que no lo mires de frente mucho tiempo.', 42423),
(1549, 'esMX', 'Aurélida brillante', '|cFFFFD200Logro: |rGloria del asaltante del Sepulcro|n|cFFFFD200Categoría: |rCalabozos y bandas', 'Si bien fue creada para defender el Sepulcro de los Primeros, ahora que su función principal está terminada, obedece tus órdenes sumisamente.', 42423);
