INSERT INTO `lfg_dungeons_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(2190, 'frFR', 'La bataille de Sylvarden', '', 42423),
(2292, 'frFR', 'Plaines Éphémères', 'L\’essence de la création se fait dévorer lentement mais sûrement. Si personne n\’intervient, c\’est la réalité entière qui finira par s\’effondrer.', 42423),
(2291, 'frFR', 'Assise de la Création', 'Lihuvim mène un combat perdu d\’avance contre la domination. À moins qu\’on ne vole à son secours, son pouvoir tombera aux mains du Geôlier.', 42423);
