INSERT INTO `mount_locale` (`ID`, `locale`, `Name_lang`, `SourceText_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(1552, 'frFR', 'Destrier de Zereth carcinisé', '|cFFFFD200Quête :|r Une mélodie énigmatique', 'Dernières représentantes de leur espèce, ces créatures mystérieuses semblent incroyablement antiques, voire intemporelles. Il se peut même qu\’elles aient été créées par les Fondateurs, car aucun schéma permettant de les synthétiser n\’a été découvert jusqu\’ici.', 42423),
(1572, 'frFR', 'Mangeur d\’âmes du gladiateur cosmique', '|cFFFFD200Haut fait :|r Gladiateur, saison 3 de Shadowlands|n|cFFFFD200Catégorie :|r Joueur contre Joueur', 'Les yeux du mangeur d\’âmes vous glacent. Mieux vaut ne pas soutenir son regard trop longtemps.', 42423),
(1480, 'frFR', 'Mangeur d\’âmes du gladiateur déchaîné', '|cFFFFD200Haut fait :|r Gladiateur, saison 2 de Shadowlands|n|cFFFFD200Catégorie :|r Joueur contre Joueur', 'Les yeux du mangeur d\’âmes vous glacent. Mieux vaut ne pas soutenir son regard trop longtemps.', 42423),
(1549, 'frFR', 'Aurélidé chatoyant', '|cFFFFD200Haut fait : |rGloire à l\’écumeur du sépulcre|n|cFFFFD200Catégorie : |rDonjons et raids', 'Créé à l\’origine pour défendre le sépulcre des Fondateurs, rôle dont il s\’est parfaitement acquitté, cet aurélidé vous obéit désormais au doigt et à l\’œil.', 42423);
