INSERT INTO `mount_locale` (`ID`, `locale`, `Name_lang`, `SourceText_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(1552, 'itIT', 'Destriero di Zereth Carcinizzato', '|cFFFFD200Missione:|r Motivazioni scatenanti', 'I pochi esemplari rimasti di queste creature misteriose sembrano essere incredibilmente antichi, quasi senza tempo. Forse sono stati creati dai Primi, poiché non è ancora stato scoperto nessuno schema per sintetizzarli.', 42423),
(1572, 'itIT', 'Mangiatore di Anime del Gladiatore Cosmico', '|cFFFFD200Impresa: |rGladiatore: Stagione 3 di Shadowlands|n|cFFFFD200Categoria: |rPvP', 'Lo sguardo di questo Mangiatore di Anime ti mette a disagio. Meglio non guardarlo negli occhi troppo a lungo.', 42423),
(1480, 'itIT', 'Mangiatore di Anime del Gladiatore Liberato', '|cFFFFD200Impresa: |rGladiatore: Stagione 2 di Shadowlands|n|cFFFFD200Categoria: |rPvP', 'Lo sguardo di questo Mangiatore di Anime ti mette a disagio. Meglio non guardarlo negli occhi troppo a lungo.', 42423),
(1549, 'itIT', 'Aurelide Scintillante', '|cFFFFD200Impresa:|r Gloria dell\'incursore del Sepolcro|n|cFFFFD200Categoria:|r Spedizioni e incursioni', 'Anche se è stato creato per difendere il Sepolcro dei Primi, ora che la sua funzione primaria si è esaurita, segue ciecamente i tuoi comandi.', 42423);
