INSERT INTO `mount_locale` (`ID`, `locale`, `Name_lang`, `SourceText_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(1552, 'ptBR', 'Corcel de Zereth Carcinizado', '|cFFFFD200Missão:|r Motivos Primaciais', 'As poucas que restam dessas criaturas parecem ser impossivelmente antigas, quase atemporais. Talvez elas tenham sido criadas pelos Primogênitos, pois ainda não se descobriu qualquer diagrama para sintetizá-las.', 42423),
(1572, 'ptBR', 'Comedor de Almas do Gladiador Cósmico', '|cFFFFD200Conquista: |rGladiador: Série 3 de Shadowlands|n|cFFFFD200Categoria: |rJogador x Jogador', 'Os olhos deste comedor de almas te causam arrepios. É melhor evitar olhar para a cara dele.', 42423),
(1480, 'ptBR', 'Comedor de Almas do Gladiador Desacorrentado', '|cFFFFD200Conquista: |rGladiador: Série 2 de Shadowlands|n|cFFFFD200Categoria: |rJogador x Jogador', 'Os olhos deste comedor de almas te causam arrepios. É melhor evitar olhar para a cara dele.', 42423),
(1549, 'ptBR', 'Aurelídeo Cintilante', '|cFFFFD200Conquista: |rGlória do saqueador do Sepulcro|n|cFFFFD200Categoria: |rMasmorras e Raides', 'Foi criada para defender o Sepulcro dos Primogênitos, mas agora que a montaria já cumpriu sua função principal, ela obedecerá suas ordens.', 42423);
