INSERT INTO `mount_locale` (`ID`, `locale`, `Name_lang`, `SourceText_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(1552, 'ruRU', 'Крабовидный зеретский бегун', '|cFFFFD200Задание:|r Главный мотив', 'Последние представители этого загадочного вида настолько древние, что над ними будто не властно время. Возможно, их даже создали сами Предвечные, потому что ни одной схемы их синтеза до наших дней не сохранилось.', 42423),
(1572, 'ruRU', 'Пожиратель душ космического гладиатора', '|cFFFFD200Достижение: |r\"Гладиатор: 3-й сезон Shadowlands\"|n|cFFFFD200Категория: |rPvP', 'Взгляд этого пожирателя душ выводит вас из равновесия. Лучше не смотреть ему в глаза слишком долго.', 42423),
(1480, 'ruRU', 'Пожиратель душ освобожденного гладиатора', '|cFFFFD200Достижение: |r\"Гладиатор: 2-й сезон Shadowlands\"|n|cFFFFD200Категория: |rPvP', 'Взгляд этого пожирателя душ выводит вас из равновесия. Лучше не смотреть ему в глаза слишком долго.', 42423),
(1549, 'ruRU', 'Мерцающий аурелид', '|cFFFFD200Достижение: |r\"Слава рейдеру Гробницы\"|n|cFFFFD200Категория: |rподземелья и рейды', 'Когда-то это существо было создано для защиты Гробницы Предвечных. Теперь его основная задача завершена, и оно покорно выполняет ваши команды.', 42423);
