INSERT INTO `mount_locale` (`ID`, `locale`, `Name_lang`, `SourceText_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(1552, 'zhCN', '蟹化的扎雷骁骑', '|cFFFFD200任务：|r主要动机', '这种古老的生物里少数仅存的个体都已经非常古老了，几乎超越了时间。它们可能是由初诞者亲手创造的，因为还没有发现合成它们的设计图。', 42423),
(1572, 'zhCN', '宇宙角斗士的噬魂者', '|cFFFFD200成就：|r角斗士：“暗影国度”第3赛季|n|cFFFFD200分类：|rPvP', '这只噬魂者的目光让你很不安，最好别盯着它的眼睛看太久。', 42423),
(1480, 'zhCN', '不羁角斗士的噬魂者', '|cFFFFD200成就：|r角斗士：“暗影国度”第2赛季|n|cFFFFD200分类：|rPvP', '这只噬魂者的目光让你很不安，最好别盯着它的眼睛看太久。', 42423),
(1549, 'zhCN', '闪光元水母', '|cFFFFD200成就：|r圣墓团队的荣耀|n|cFFFFD200分类：|r地下城与团队副本', '创造它本来是为了守卫初诞者圣墓。它的主要职责完成后，就开始服从你的命令。', 42423);
