INSERT INTO `mount_locale` (`ID`, `locale`, `Name_lang`, `SourceText_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(1552, 'zhTW', '蟹化澤瑞斯戰騎', '|cFFFFD200任務：|r重要動機', '這種僅存的神祕生物看起來異常古老，看起來幾乎像是永生不死的。牠們說不定是首創者的造物，因為目前我們還沒發現任何能夠合成出這種生物的結構圖。', 42423),
(1572, 'zhTW', '宇宙鬥士的噬魂者', '|cFFFFD200成就：|r鬥士：暗影之境第3季|n|cFFFFD200類別：|r玩家對玩家', '這個噬魂者的凝視讓你莫名恐懼，最好別盯著看。', 42423),
(1480, 'zhTW', '無束鬥士的噬魂者', '|cFFFFD200成就：|r鬥士：暗影之境第2季|n|cFFFFD200類別：|r玩家對玩家', '這個噬魂者的凝視讓你莫名恐懼，最好別盯著看。', 42423),
(1549, 'zhTW', '閃亮原基水母', '|cFFFFD200成就：|r聖塚團隊高手的榮耀|n|cFFFFD200類別：|r地城與團隊', '牠原先被創造的目的是要守護首創者聖塚。如今主要任務完成了，牠開始忠實遵從你的指令。', 42423);
